    --line-d:rgba(244,236,229,.16);
    --serif:'Playfair Display',Georgia,serif;
    --sans:'Jost',system-ui,sans-serif;
    --ease:cubic-bezier(.76,0,.24,1);
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{background:var(--nude);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
  body{cursor:none}
  a{color:inherit;text-decoration:none}
  img{display:block;width:100%;height:100%;object-fit:cover}
  ::selection{background:var(--wine);color:var(--nude)}
  .wrap{width:min(92%,1280px);margin-inline:auto}
  .serif{font-family:var(--serif)}
  em{font-style:italic;color:var(--wine)}
  .eyebrow{font-size:.68rem;letter-spacing:.34em;text-transform:uppercase;color:var(--wine);font-weight:500;display:inline-flex;align-items:center;gap:.8rem}
  .eyebrow::before{content:"";width:30px;height:1px;background:var(--wine)}
  .eyebrow.inv{color:var(--blush)}.eyebrow.inv::before{background:var(--blush)}
  .secnum{font-family:var(--serif);font-style:italic;font-size:.9rem;color:var(--blush2)}

  /* CURSOR */
  .cursor{position:fixed;top:0;left:0;width:12px;height:12px;border-radius:50%;background:var(--wine2);pointer-events:none;z-index:9999;mix-blend-mode:difference;transform:translate(-50%,-50%)}
  .cursor-ring{position:fixed;top:0;left:0;width:44px;height:44px;border:1px solid var(--ink);border-radius:50%;pointer-events:none;z-index:9998;transform:translate(-50%,-50%);transition:width .3s var(--ease),height .3s var(--ease),background .3s,border-color .3s}
  .cursor-ring.grow{width:84px;height:84px;background:rgba(110,43,58,.1);border-color:var(--wine)}
  @media(hover:none){body{cursor:auto}.cursor,.cursor-ring{display:none}}

  /* PRELOADER */
  #preloader{position:fixed;inset:0;background:var(--ink);color:var(--nude);z-index:10000;display:flex;flex-direction:column;justify-content:space-between;padding:clamp(1.4rem,4vw,3rem)}
  #preloader .top{display:flex;justify-content:space-between;align-items:center;font-size:.68rem;letter-spacing:.32em;text-transform:uppercase;opacity:.7}
  #preloader .count{font-family:var(--serif);font-style:italic;font-size:clamp(5rem,22vw,18rem);line-height:.8;color:var(--blush)}
  #preloader .bar{height:1px;background:rgba(244,236,229,.18);overflow:hidden}
  #preloader .bar i{display:block;height:100%;width:0;background:var(--blush)}

  /* NAV */
  header{position:fixed;top:0;left:0;width:100%;z-index:900;transition:background .4s,backdrop-filter .4s}
  header.scrolled{background:rgba(244,236,229,.86);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
  .nav{display:flex;align-items:center;justify-content:space-between;padding:1.3rem 0}
  .logo{font-family:var(--serif);font-size:1.7rem;letter-spacing:.18em;font-weight:500}
  .logo span{font-size:.54rem;letter-spacing:.3em;color:var(--wine);font-family:var(--sans);display:block;margin-top:.2rem}
  .menu{display:flex;gap:2.1rem;list-style:none;font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;font-weight:400}
  .menu a{position:relative;padding:.3rem 0}
  .menu a::after{content:"";position:absolute;left:0;bottom:-2px;width:0;height:1px;background:var(--wine);transition:width .4s var(--ease)}
  .menu a:hover::after{width:100%}
  .nav-right{display:flex;align-items:center;gap:1.3rem}
  .lang{display:flex;gap:.2rem;border:1px solid var(--line);border-radius:999px;padding:.22rem}
  .lang button{border:0;background:transparent;font-family:var(--sans);font-size:.64rem;letter-spacing:.14em;padding:.35rem .6rem;border-radius:999px;cursor:none;color:var(--mut-l);transition:.3s}
  .lang button.active{background:var(--ink);color:var(--nude)}
  .burger{display:none;flex-direction:column;gap:5px;background:none;border:0;cursor:none}
  .burger i{width:26px;height:1px;background:var(--ink);transition:.3s}

  /* BUTTONS */
  .btn{position:relative;display:inline-flex;align-items:center;gap:.7rem;padding:.95rem 1.8rem;font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;font-weight:500;overflow:hidden;cursor:none;border:1px solid var(--ink);border-radius:999px;transition:color .4s var(--ease)}
  .btn .fill{position:absolute;inset:0;background:var(--ink);transform:translateY(101%);transition:transform .5s var(--ease);z-index:0}
  .btn span{position:relative;z-index:1}
  .btn:hover{color:var(--nude)}
  .btn:hover .fill{transform:translateY(0)}
  .btn.solid{background:var(--wine);color:var(--nude);border-color:var(--wine)}
  .btn.solid .fill{background:var(--ink);transform:translateY(0)}
  .btn.solid:hover .fill{transform:translateY(-101%)}
  .btn.inv{border-color:var(--nude);color:var(--nude)}
  .btn.inv .fill{background:var(--blush)}
  .btn.inv:hover{color:var(--ink)}
  .btn.ghost{border-color:var(--line);color:var(--ink)}

  /* HERO */
  .hero{min-height:100vh;position:relative;display:flex;align-items:center;padding:clamp(7rem,13vh,9rem) 0 clamp(3rem,7vh,5rem);overflow:hidden}
  .hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(2rem,5vw,5rem);align-items:center}
  .hero h1{font-family:var(--serif);font-weight:400;font-size:clamp(2.8rem,8vw,7rem);line-height:.98;letter-spacing:-.01em}
  .hero h1 .word{display:inline-block;overflow:hidden;vertical-align:top}
  .hero h1 .word i{display:inline-block;font-style:normal;transform:translateY(110%)}
  .hero h1 em{font-style:italic;color:var(--wine)}
  .hero-foot{display:flex;align-items:center;gap:1.6rem;margin-top:2.2rem;flex-wrap:wrap}
  .hero-foot p{color:var(--mut-l);font-size:.96rem;line-height:1.7;max-width:34ch}
  .hero-cta{display:flex;gap:1rem;flex-wrap:wrap}
  .hero-media{position:relative;aspect-ratio:4/5;overflow:hidden}
  .hero-media img{transform:scale(1.12)}
  .hero-media .frame{position:absolute;inset:14px;border:1px solid rgba(244,236,229,.6);pointer-events:none;z-index:2}
  .hero-media .pgnum{position:absolute;top:18px;right:22px;z-index:3;font-family:var(--serif);font-style:italic;color:var(--nude);font-size:.9rem;letter-spacing:.1em}
  .hero-media .vtext{position:absolute;left:-6px;top:50%;transform:translateY(-50%) rotate(-90deg);transform-origin:left;font-size:.6rem;letter-spacing:.4em;text-transform:uppercase;color:var(--nude);z-index:3;white-space:nowrap}
  .open-badge{position:absolute;bottom:18px;left:18px;z-index:3;display:inline-flex;align-items:center;gap:.6rem;background:rgba(33,28,27,.7);backdrop-filter:blur(8px);color:var(--nude);font-size:.66rem;letter-spacing:.16em;text-transform:uppercase;padding:.6rem 1rem;border-radius:999px}
  .open-badge .dot{width:8px;height:8px;border-radius:50%}
  .open-badge.open .dot{background:var(--blush);box-shadow:0 0 10px var(--blush);animation:pulse 1.6s infinite}
  .open-badge.closed .dot{background:var(--mut-d)}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
  .scroll-ind{position:absolute;bottom:1.4rem;left:50%;transform:translateX(-50%);z-index:2;font-size:.6rem;letter-spacing:.3em;text-transform:uppercase;color:var(--mut-l);display:flex;flex-direction:column;align-items:center;gap:.6rem}
  .scroll-ind i{width:1px;height:38px;background:var(--mut-l);animation:drop 1.8s var(--ease) infinite}
  @keyframes drop{0%{transform:scaleY(0);transform-origin:top}50%{transform:scaleY(1);transform-origin:top}51%{transform-origin:bottom}100%{transform:scaleY(0);transform-origin:bottom}}

  /* MARQUEE */
  .marquee{background:var(--ink);color:var(--nude);padding:1.3rem 0;overflow:hidden;border-block:1px solid rgba(244,236,229,.1)}
  .marquee .track{display:flex;gap:3rem;white-space:nowrap;width:max-content;font-family:var(--serif);font-style:italic;font-size:clamp(1.3rem,3vw,2.2rem)}
  .marquee .track span{display:inline-flex;align-items:center;gap:3rem}
  .marquee .track em{color:var(--blush);font-style:normal;font-family:var(--sans);font-size:.66rem;letter-spacing:.24em;text-transform:uppercase}
  .marquee .dot{width:6px;height:6px;border-radius:50%;background:var(--wine2);display:inline-block}

  /* ABOUT */
  .about{padding:clamp(5rem,12vh,10rem) 0}
  .about-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(2rem,6vw,6rem);align-items:center}
  .about .media{position:relative;aspect-ratio:4/5;overflow:hidden}
  .about .media .reveal-mask{position:absolute;inset:0;background:var(--wine);transform-origin:left;z-index:2}
  .about h2{font-family:var(--serif);font-weight:400;font-size:clamp(2rem,5vw,4.2rem);line-height:1.06}
  .about h2 .ln{display:block;overflow:hidden}
  .about h2 .ln i{display:inline-block;font-style:normal;transform:translateY(110%)}
  .about .vals{margin-top:2.2rem;display:grid;grid-template-columns:repeat(3,1fr);gap:1.4rem}
  .about .vals div{border-top:1px solid var(--line);padding-top:1rem}
  .about .vals b{font-family:var(--serif);font-size:1.2rem;font-weight:500;display:block}
  .about .vals span{font-size:.8rem;color:var(--mut-l);line-height:1.5;display:block;margin-top:.4rem}

  /* SERVICES (editorial carta) */
  .services{background:var(--nude2);padding:clamp(5rem,12vh,10rem) 0;border-block:1px solid var(--line)}
  .sec-head{display:flex;justify-content:space-between;align-items:flex-end;gap:2rem;margin-bottom:clamp(2.5rem,6vh,4rem);flex-wrap:wrap}
  .sec-head h2{font-family:var(--serif);font-weight:400;font-size:clamp(2.2rem,6vw,5rem);line-height:1}
  .sec-head .note{color:var(--mut-l);font-size:.82rem;letter-spacing:.04em;max-width:26ch;text-align:right;line-height:1.6}
  .srv-list{border-top:1px solid var(--line)}
  .srv{display:grid;grid-template-columns:60px 1.4fr 1fr auto auto;gap:1.4rem;align-items:center;padding:clamp(1.3rem,2.5vw,2rem) 0;border-bottom:1px solid var(--line);transition:padding .4s var(--ease)}
  .srv:hover{padding-left:.6rem}
  .srv .n{font-family:var(--serif);font-style:italic;color:var(--blush2);font-size:1.1rem}
  .srv .nm{font-family:var(--serif);font-size:clamp(1.3rem,2.6vw,2rem);font-weight:500;line-height:1.05}
  .srv .ds{color:var(--mut-l);font-size:.84rem;line-height:1.55;margin-top:.3rem}
  .srv .dur{font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut-l)}
  .srv .pr{font-family:var(--serif);font-size:1.3rem;color:var(--wine);white-space:nowrap}
  .add{border:1px solid var(--line);background:transparent;border-radius:999px;padding:.6rem 1.1rem;font-size:.66rem;letter-spacing:.14em;text-transform:uppercase;cursor:none;transition:.3s;font-family:var(--sans);color:var(--ink);white-space:nowrap}
  .add:hover{border-color:var(--wine);color:var(--wine)}
  .add.in{background:var(--wine);color:var(--nude);border-color:var(--wine)}

  /* LOOKBOOK */
  .lookbook{padding:clamp(5rem,12vh,10rem) 0}
  .masonry{columns:3;column-gap:1rem}
  .masonry .mi{break-inside:avoid;margin-bottom:1rem;position:relative;overflow:hidden;cursor:none}
  .masonry .mi img{transition:transform 1.1s var(--ease)}
  .masonry .mi:hover img{transform:scale(1.06)}
  .masonry .mi::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(33,28,27,.7));opacity:0;transition:opacity .4s}
  .masonry .mi:hover::after{opacity:1}
  .masonry .mi .cap{position:absolute;left:0;right:0;bottom:0;padding:1.2rem;z-index:2;color:var(--nude);transform:translateY(10px);opacity:0;transition:.4s var(--ease)}
  .masonry .mi:hover .cap{transform:translateY(0);opacity:1}
  .masonry .mi .cap .c{font-size:.6rem;letter-spacing:.2em;text-transform:uppercase;color:var(--blush)}
  .masonry .mi .cap h3{font-family:var(--serif);font-size:1.2rem;font-weight:500;margin-top:.3rem}
  .masonry .mi .zoom{position:absolute;top:1rem;right:1rem;z-index:2;width:38px;height:38px;border-radius:50%;background:rgba(244,236,229,.9);color:var(--ink);display:grid;place-items:center;opacity:0;transform:scale(.8);transition:.4s var(--ease)}
  .masonry .mi:hover .zoom{opacity:1;transform:scale(1)}

  /* LIGHTBOX */
  .lightbox{position:fixed;inset:0;z-index:9600;background:rgba(33,28,27,.94);backdrop-filter:blur(8px);display:none;place-items:center;padding:2rem}
  .lightbox .lb-img{max-width:min(90vw,900px);max-height:78vh;border:1px solid var(--line-d)}
  .lightbox .lb-img img{width:auto;height:auto;max-width:min(90vw,900px);max-height:78vh;object-fit:contain}
  .lightbox .lb-cap{text-align:center;color:var(--nude);margin-top:1.2rem;font-family:var(--serif);font-style:italic;font-size:1.1rem}
  .lightbox .lb-cap small{display:block;font-family:var(--sans);font-style:normal;font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;color:var(--blush);margin-bottom:.4rem}
  .lb-btn{position:absolute;top:50%;transform:translateY(-50%);width:50px;height:50px;border-radius:50%;border:1px solid var(--line-d);background:transparent;color:var(--nude);font-size:1.2rem;cursor:none;transition:.3s}
  .lb-btn:hover{background:var(--wine);border-color:var(--wine)}
  .lb-prev{left:2rem}.lb-next{right:2rem}
  .lb-close{position:absolute;top:1.6rem;right:1.8rem;width:46px;height:46px;border-radius:50%;border:1px solid var(--line-d);background:transparent;color:var(--nude);font-size:1.2rem;cursor:none;transition:.3s}
  .lb-close:hover{background:var(--wine);border-color:var(--wine)}

  /* BOOKING */
  .booking{background:var(--ink);color:var(--nude);padding:clamp(5rem,12vh,10rem) 0}
  .booking .sec-head h2{color:var(--nude)}
  .booking .sec-head .note{color:var(--mut-d)}
  .bk-grid{display:grid;grid-template-columns:1.5fr .8fr;gap:clamp(2rem,5vw,4rem);align-items:start}
  .steps{display:flex;flex-direction:column;gap:1.4rem}
  .step{border:1px solid var(--line-d);border-radius:14px;padding:clamp(1.3rem,2.5vw,1.8rem);background:rgba(255,255,255,.02);transition:border-color .4s}
  .step.active{border-color:var(--blush2)}
  .step.done{border-color:rgba(227,195,188,.4)}
  .step-h{display:flex;align-items:center;gap:1rem;margin-bottom:1.2rem}
  .step-h .sn{font-family:var(--serif);font-style:italic;font-size:1.3rem;color:var(--blush);width:30px}
  .step-h h3{font-family:var(--serif);font-size:1.3rem;font-weight:500}
  .step-h .chk{margin-left:auto;color:var(--blush);opacity:0;transition:.3s}
  .step.done .step-h .chk{opacity:1}
  .step-body{display:none}
  .step.active .step-body,.step.done .step-body{display:block}
  .cart-empty{color:var(--mut-d);font-size:.86rem;line-height:1.6}
  .cart-list{display:flex;flex-direction:column;gap:.7rem}
  .cart-row{display:flex;align-items:center;gap:1rem;border:1px solid var(--line-d);border-radius:10px;padding:.8rem 1rem}
  .cart-row .cn{font-family:var(--serif);font-size:1.05rem;flex:1}
  .cart-row .cp{font-size:.8rem;color:var(--blush);font-family:var(--sans)}
  .cart-row .rm{background:none;border:0;color:var(--mut-d);cursor:none;font-size:1.1rem;transition:.3s}
  .cart-row .rm:hover{color:var(--blush)}
  .pro-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:.8rem}
  .pro{border:1px solid var(--line-d);border-radius:12px;padding:.9rem;display:flex;align-items:center;gap:.9rem;cursor:none;transition:.3s}
  .pro:hover{border-color:var(--blush2)}
  .pro.sel{border-color:var(--blush);background:rgba(227,195,188,.08)}
  .pro .av{width:46px;height:46px;border-radius:50%;overflow:hidden;flex:none}
  .pro .pn{font-family:var(--serif);font-size:1.05rem}
  .pro .pr2{font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut-d)}
  .day-chips{display:flex;gap:.6rem;flex-wrap:wrap;margin-bottom:1.2rem}
  .dchip{border:1px solid var(--line-d);border-radius:12px;padding:.7rem 1rem;text-align:center;cursor:none;transition:.3s;min-width:64px}
  .dchip:hover{border-color:var(--blush2)}
  .dchip.sel{border-color:var(--blush);background:rgba(227,195,188,.1)}
  .dchip .wd{font-size:.6rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut-d)}
  .dchip .dn{font-family:var(--serif);font-size:1.3rem;margin-top:.2rem}
  .dchip .sp{font-size:.56rem;color:var(--blush);letter-spacing:.08em;margin-top:.2rem;text-transform:uppercase}
  .slot-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:.5rem}
  .slot{border:1px solid var(--line-d);border-radius:8px;padding:.6rem 0;text-align:center;font-family:var(--sans);font-size:.82rem;cursor:none;transition:.3s;background:transparent;color:var(--nude)}
  .slot:hover:not(:disabled){border-color:var(--blush2)}
  .slot.sel{background:var(--blush);color:var(--ink);border-color:var(--blush)}
  .slot:disabled{opacity:.3;cursor:not-allowed;text-decoration:line-through}
  .data-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
  .dfield label{display:block;font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--mut-d);margin-bottom:.5rem}
  .dfield input{width:100%;background:transparent;border:0;border-bottom:1px solid var(--line-d);padding:.6rem 0;color:var(--nude);font-family:var(--sans);font-size:.92rem;outline:none;cursor:none;transition:border-color .3s}
  .dfield input:focus{border-color:var(--blush)}
  .dfield.full{grid-column:1/-1}
  /* summary */
  .summary{position:sticky;top:90px;border:1px solid var(--line-d);border-radius:14px;padding:clamp(1.4rem,3vw,2rem);background:rgba(255,255,255,.03)}
  .summary h4{font-family:var(--serif);font-size:1.3rem;font-weight:500;margin-bottom:1.2rem}
  .sum-row{display:flex;justify-content:space-between;gap:1rem;padding:.7rem 0;border-bottom:1px solid var(--line-d);font-size:.86rem;color:var(--mut-d)}
  .sum-row b{color:var(--nude);font-weight:500;text-align:right}
  .sum-total{display:flex;justify-content:space-between;align-items:baseline;margin-top:1.2rem}
  .sum-total .t{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:var(--blush)}
  .sum-total .v{font-family:var(--serif);font-size:2rem;color:var(--nude)}
  .sum-dur{font-size:.74rem;color:var(--mut-d);text-align:right;margin-top:.2rem}
  .summary .btn{width:100%;justify-content:center;margin-top:1.6rem}
  .summary .btn:disabled{opacity:.4;cursor:not-allowed}

  /* TEAM */
  .team{padding:clamp(5rem,12vh,10rem) 0}
  .team-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:clamp(1.2rem,2.5vw,2rem)}
  .member{cursor:none}
  .member .ph{aspect-ratio:3/4;overflow:hidden;position:relative}
  .member .ph img{transition:transform 1.1s var(--ease),filter .6s}
  .member:hover .ph img{transform:scale(1.05)}
  .member .ov{position:absolute;inset:0;background:linear-gradient(180deg,transparent 40%,rgba(110,43,58,.85));display:flex;flex-direction:column;justify-content:flex-end;padding:1.2rem;opacity:0;transition:.4s}
  .member:hover .ov{opacity:1}
  .member .ov span{font-size:.7rem;letter-spacing:.08em;color:var(--nude);line-height:1.5}
  .member h3{font-family:var(--serif);font-size:1.3rem;font-weight:500;margin-top:1rem}
  .member .role{font-size:.66rem;letter-spacing:.16em;text-transform:uppercase;color:var(--wine);margin-top:.3rem}

  /* STATS */
  .stats{background:var(--nude2);padding:clamp(4rem,9vh,7rem) 0;border-block:1px solid var(--line)}
  .stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:2rem;text-align:center}
  .stat .num{font-family:var(--serif);font-size:clamp(3rem,7vw,6rem);line-height:1;color:var(--ink);font-weight:400}
  .stat .num em{color:var(--wine)}
  .stat .lbl{font-size:.7rem;letter-spacing:.2em;text-transform:uppercase;margin-top:.8rem;color:var(--mut-l)}

  /* TESTI (editorial grid) */
  .testi{padding:clamp(5rem,12vh,9rem) 0}
  .testi-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(1.4rem,3vw,2.4rem)}
  .quote{border-top:1px solid var(--line);padding-top:1.6rem}
  .quote .mk{font-family:var(--serif);font-size:3rem;line-height:.4;color:var(--blush2);display:block;height:1.4rem}
  .quote p{font-family:var(--serif);font-style:italic;font-size:clamp(1.1rem,1.8vw,1.4rem);line-height:1.4;margin:1rem 0 1.2rem}
  .quote cite{font-style:normal;font-size:.7rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut-l)}

  /* CTA + CONTACT */
  .contact{background:var(--wine);color:var(--nude);padding:clamp(5rem,12vh,9rem) 0}
  .contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(2rem,6vw,6rem);align-items:center}
