  .cfield label{display:block;font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--mut-d);margin-bottom:.5rem}
  .cfield input,.cfield textarea{width:100%;background:transparent;border:0;border-bottom:1px solid rgba(244,236,229,.3);padding:.6rem 0;color:var(--nude);font-family:var(--sans);font-size:.92rem;outline:none;cursor:none;transition:border-color .3s}
  .cfield textarea{resize:vertical;min-height:70px}
  .cfield input:focus,.cfield textarea:focus{border-color:var(--blush)}
  .contact .btn{border-color:var(--nude);color:var(--nude)}
  .contact .btn .fill{background:var(--nude)}
  .contact .btn:hover{color:var(--wine)}

