  .res-ok p{color:var(--mut-l);margin:1rem 0 1.6rem;line-height:1.6}
  .res-ok .det{text-align:left;border-top:1px solid var(--line);margin-bottom:1.6rem}
  .res-ok .det div{display:flex;justify-content:space-between;padding:.5rem 0;font-size:.84rem;border-bottom:1px solid var(--line)}
  .res-ok .det div span{color:var(--mut-l)}

  /* FLOATING BOOKING BAR */
  .floatbar{position:fixed;left:50%;bottom:1.4rem;transform:translate(-50%,140%);z-index:800;display:flex;align-items:center;gap:1.2rem;background:var(--ink);color:var(--nude);border:1px solid var(--line-d);border-radius:999px;padding:.6rem .6rem .6rem 1.4rem;box-shadow:0 24px 50px -20px rgba(0,0,0,.6);transition:transform .5s var(--ease)}
  .floatbar.show{transform:translate(-50%,0)}
  .floatbar .ft{font-size:.82rem}
  .floatbar .ft b{font-family:var(--serif);font-size:1.1rem;color:var(--blush)}
  .floatbar .btn{padding:.7rem 1.4rem}

  /* FOOTER */
  footer{background:var(--ink);color:var(--nude);padding:clamp(4rem,8vh,6rem) 0 2rem}
  .foot-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:2.5rem;padding-bottom:3rem;border-bottom:1px solid var(--line-d)}
  .foot-brand .logo{color:var(--nude)}
  .foot-brand p{color:var(--mut-d);margin-top:1.2rem;max-width:32ch;line-height:1.6;font-size:.9rem}
  .foot-col h4{font-size:.66rem;letter-spacing:.22em;text-transform:uppercase;color:var(--blush);margin-bottom:1.2rem}
  .foot-col a{display:block;font-size:.9rem;padding:.35rem 0;color:rgba(244,236,229,.75);transition:.3s}
  .foot-col a:hover{color:var(--nude);padding-left:.4rem}
  .foot-bot{display:flex;justify-content:space-between;align-items:center;padding-top:2rem;font-size:.72rem;letter-spacing:.08em;color:var(--mut-d);flex-wrap:wrap;gap:1rem}

  .img-fallback{background:linear-gradient(135deg,var(--blush2),var(--wine))!important}
  .img-fallback img{display:none}

  @media(max-width:980px){
