    .srv{grid-template-columns:40px 1fr auto;grid-template-areas:"n nm pr" "n ds ds" "n add add";row-gap:.6rem}
    .srv .n{grid-area:n}.srv .nm{grid-area:nm}.srv .pr{grid-area:pr;justify-self:end}.srv .ds{grid-area:ds}.srv .dur{display:none}.srv .add{grid-area:add;justify-self:start}
    .summary{position:static}
  }
  @media(max-width:560px){
