/* ============ SERVICES ============ */
function renderServices(){
  const wrap=document.getElementById('srvList');wrap.innerHTML='';
  SERVICES.forEach((s,i)=>{
    const inCart=cart.has(s.id);
    const row=document.createElement('div');row.className='srv';
    row.innerHTML=`<span class="n">0${i+1}</span>
      <div><div class="nm">${L(s.n)}</div><div class="ds">${L(s.d)}</div></div>
      <span class="dur">${s.dur} min</span>
      <span class="pr">${fmt(s.price)}</span>
      <button class="add ${inCart?'in':''}" data-id="${s.id}">${inCart?L('added'):L('add')}</button>`;
    wrap.appendChild(row);
  });
  wrap.querySelectorAll('.add').forEach(b=>b.addEventListener('click',()=>toggleService(b.dataset.id)));
  bindCursor();
}
function toggleService(id){
  if(cart.has(id))cart.delete(id);else cart.add(id);
  renderServices();renderCart();renderSummary();updateSteps();updateFloat();
}

/* ============ LOOKBOOK + LIGHTBOX ============ */
function renderLook(){
  const m=document.getElementById('masonry');m.innerHTML='';
  LOOK.forEach((it,i)=>{
    const d=document.createElement('div');d.className='mi';
    d.innerHTML=`<img data-src="${it.img}" alt="" style="aspect-ratio:4/${(it.h/100).toFixed(1)}"><span class="zoom">⤢</span><div class="cap"><span class="c">${L(it.c)}</span><h3>${L(it.t)}</h3></div>`;
    d.addEventListener('click',()=>openLB(i));
    m.appendChild(d);
  });
  lazy(m);bindCursor();
  gsap.utils.toArray('.mi').forEach(el=>gsap.from(el,{y:40,opacity:0,duration:.8,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 90%'}}));
}
let lbIdx=0;
const lightbox=document.getElementById('lightbox');
function openLB(i){lbIdx=i;paintLB();gsap.set(lightbox,{display:'grid'});if(!reduce)gsap.fromTo(lightbox,{opacity:0},{opacity:1,duration:.3});document.addEventListener('keydown',lbKey);}
function closeLB(){if(reduce){gsap.set(lightbox,{display:'none'});}else gsap.to(lightbox,{opacity:0,duration:.3,onComplete:()=>gsap.set(lightbox,{display:'none',opacity:1})});document.removeEventListener('keydown',lbKey);}
function paintLB(){const it=LOOK[lbIdx];document.getElementById('lbImg').src=it.img;document.getElementById('lbCat').textContent=L(it.c);document.getElementById('lbCap').textContent=L(it.t);}
function lbNav(d){lbIdx=(lbIdx+d+LOOK.length)%LOOK.length;paintLB();}
function lbKey(e){if(e.key==='Escape')closeLB();if(e.key==='ArrowRight')lbNav(1);if(e.key==='ArrowLeft')lbNav(-1);}
document.getElementById('lbClose').addEventListener('click',closeLB);
document.getElementById('lbPrev').addEventListener('click',()=>lbNav(-1));
document.getElementById('lbNext').addEventListener('click',()=>lbNav(1));
lightbox.addEventListener('click',e=>{if(e.target===lightbox)closeLB();});

/* ============ BOOKING ============ */
function renderCart(){
  const body=document.getElementById('cartBody');
  if(cart.size===0){body.innerHTML=`<p class="cart-empty">${L('bk_empty')}</p><a href="#serveis" class="btn ghost" style="margin-top:1rem"><span>${L('bk_goadd')}</span><span class="fill"></span></a>`;return;}
  let html='<div class="cart-list">';
  cart.forEach(id=>{const s=SERVICES.find(x=>x.id===id);html+=`<div class="cart-row"><span class="cn">${L(s.n)}</span><span class="cp">${s.dur} min · ${fmt(s.price)}</span><button class="rm" data-id="${id}" aria-label="remove">✕</button></div>`;});
  html+='</div>';body.innerHTML=html;
  body.querySelectorAll('.rm').forEach(b=>b.addEventListener('click',()=>toggleService(b.dataset.id)));
  bindCursor();
}
function renderPros(){
  const g=document.getElementById('proGrid');g.innerHTML='';
  PROS.forEach(p=>{
    const d=document.createElement('div');d.className='pro'+(selPro===p.id?' sel':'');
    d.innerHTML=`<div class="av"><img data-src="${p.img}" alt=""></div><div><div class="pn">${L(p.n)}</div><div class="pr2">${L(p.r)}</div></div>`;
    d.addEventListener('click',()=>{selPro=p.id;renderPros();renderSummary();updateSteps();});
    g.appendChild(d);
  });
  lazy(g);bindCursor();
}
function dayLabel(date,i){
  const wd=L('d'+date.getDay());
  let sp='';if(i===0)sp=L('today');else if(i===1)sp=L('tomorrow');
  return {wd:wd.slice(0,3),dn:date.getDate(),sp,iso:date.toISOString().slice(0,10)};
}
function renderDays(){
  const c=document.getElementById('dayChips');c.innerHTML='';
  const today=new Date();
  for(let i=0;i<7;i++){
    const date=new Date(today);date.setDate(today.getDate()+i);
    const dl=dayLabel(date,i);
    const closed=HOURS.find(h=>h[0]===date.getDay());
    const isClosed=closed&&closed[1]===null;
    const d=document.createElement('div');d.className='dchip'+(selDay===dl.iso?' sel':'');
    if(isClosed)d.style.opacity='.35';
    d.innerHTML=`<div class="wd">${dl.wd}</div><div class="dn">${dl.dn}</div><div class="sp">${isClosed?L('closed'):dl.sp}</div>`;
    if(!isClosed)d.addEventListener('click',()=>{selDay=dl.iso;selSlot=null;renderDays();renderSlots();renderSummary();updateSteps();});
    c.appendChild(d);
  }
  bindCursor();
}
function renderSlots(){
  const g=document.getElementById('slotGrid');g.innerHTML='';
  const di=selDay?new Date(selDay).getDay():0;
  SLOTS.forEach((s,idx)=>{
    const busy=((di*7+idx)%5===0);
    const b=document.createElement('button');b.className='slot'+(selSlot===s?' sel':'');b.textContent=s;b.disabled=busy;
    if(busy)b.title=L('full');
    if(!busy)b.addEventListener('click',()=>{selSlot=s;renderSlots();renderSummary();updateSteps();});
    g.appendChild(b);
  });
  bindCursor();
}
function renderTeam(){
  const g=document.getElementById('teamGrid');g.innerHTML='';
  PROS.forEach((p,i)=>{
    const d=document.createElement('div');d.className='member';
    d.innerHTML=`<div class="ph"><img data-src="${p.img.replace('w=300','w=700')}" alt=""><div class="ov"><span>${L('pr'+(i+1)+'_s')}</span></div></div><h3>${L(p.n)}</h3><div class="role">${L(p.r)}</div>`;
    g.appendChild(d);
  });
  lazy(g);bindCursor();
  gsap.utils.toArray('.member').forEach(el=>gsap.from(el,{y:40,opacity:0,duration:.8,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 88%'}}));
}
function totals(){let price=0,dur=0;cart.forEach(id=>{const s=SERVICES.find(x=>x.id===id);price+=s.price;dur+=s.dur;});return {price,dur};}
function renderSummary(){
  const rows=document.getElementById('sumRows');const t=totals();
  let html='';
  cart.forEach(id=>{const s=SERVICES.find(x=>x.id===id);html+=`<div class="sum-row"><span>${L(s.n)}</span><b>${fmt(s.price)}</b></div>`;});
  html+=`<div class="sum-row"><span>${L('bk_s2')}</span><b>${selPro?L(PROS.find(p=>p.id===selPro).n):L('sum_none')}</b></div>`;
  html+=`<div class="sum-row"><span>${L('bk_s3')}</span><b>${selDay&&selSlot?(new Date(selDay).toLocaleDateString(curLang==='en'?'en-GB':curLang==='es'?'es-ES':'ca-ES',{day:'numeric',month:'short'}))+' · '+selSlot:L('sum_none')}</b></div>`;
  rows.innerHTML=html;
  document.getElementById('sumTotal').textContent=fmt(t.price);
  document.getElementById('sumDur').textContent=t.dur?`${L('sum_dur')}: ${t.dur} min`:'';
  const ok=cart.size>0&&selPro&&selDay&&selSlot;
  document.getElementById('bkConfirm').disabled=!ok;
}
function updateSteps(){
  const steps=[cart.size>0,!!selPro,!!(selDay&&selSlot)];
  document.querySelectorAll('#steps .step').forEach((st,i)=>{
    if(i>=3)return;
    const done=steps[i];const active=!done&&(i===0||steps[i-1]);
    st.classList.toggle('done',done);st.classList.toggle('active',active||(i===3&&steps[2]));
  });
  const s4=document.querySelector('#steps .step[data-step="4"]');
  s4.classList.toggle('active',steps[0]&&steps[1]&&steps[2]);
  s4.classList.toggle('done',false);
}
function updateFloat(){
  const t=totals();const bar=document.getElementById('floatbar');
  document.getElementById('floatCount').textContent=cart.size;
  document.getElementById('floatTotal').textContent=fmt(t.price);
  bar.classList.toggle('show',cart.size>0);
}

/* ============ OPEN / CLOSED (live) ============ */
function isOpenNow(){
  const now=new Date();const d=now.getDay();const mins=now.getHours()*60+now.getMinutes();
  const rule=HOURS.find(h=>h[0]===d);
  if(!rule||rule[1]===null)return false;
  const[a,b]=rule[1].split(' – ').map(t=>{const[h,m]=t.split(':').map(Number);return h*60+m;});
  return mins>=a&&mins<=b;
}
function updateOpen(){
  const open=isOpenNow();const txt=open?L('open'):L('closed');
  const badge=document.getElementById('openBadge');badge.className='open-badge '+(open?'open':'closed');
  document.getElementById('openTxt').textContent=txt;
  document.getElementById('openTxt2').textContent=txt;
}
function renderHours(){
  const list=document.getElementById('hoursList');list.innerHTML='';
  const names=[L('d1')+' – '+L('d5'),L('d6'),L('d0')];
  HOURS.forEach((h,i)=>{
    const d=document.createElement('div');d.className='hr';
    d.innerHTML=`<span class="d">${names[i]}</span><span>${h[1]===null?L('closed'):h[1]}</span>`;
    list.appendChild(d);
  });
}

/* ============ CONFIRM ============ */
const resOk=document.getElementById('resOk');
document.getElementById('bkConfirm').addEventListener('click',()=>{
  const name=document.getElementById('bkName').value.trim(),phone=document.getElementById('bkPhone').value.trim(),email=document.getElementById('bkEmail').value.trim();
  if(!name||!phone||!email){gsap.fromTo('#steps .step[data-step="4"]',{x:-6},{x:6,duration:.06,repeat:3,yoyo:true});document.querySelector('#steps .step[data-step="4"]').scrollIntoView({behavior:'smooth',block:'center'});return;}
  const t=totals();const when=(new Date(selDay).toLocaleDateString(curLang==='en'?'en-GB':curLang==='es'?'es-ES':'ca-ES',{weekday:'long',day:'numeric',month:'long'}))+' · '+selSlot;
  const serv=[...cart].map(id=>L(SERVICES.find(x=>x.id===id).n)).join(', ');
  document.getElementById('okDet').innerHTML=`<div><span>${L('ok_serv')}</span><b>${serv}</b></div><div><span>${L('ok_pro')}</span><b>${L(PROS.find(p=>p.id===selPro).n)}</b></div><div><span>${L('ok_when')}</span><b>${when}</b></div><div><span>${L('sum_total')}</span><b>${fmt(t.price)}</b></div>`;
  gsap.set(resOk,{display:'grid'});
  if(reduce){gsap.set(resOk.querySelector('.card'),{opacity:1,scale:1});return;}
  gsap.fromTo(resOk,{opacity:0},{opacity:1,duration:.3});
  gsap.fromTo(resOk.querySelector('.card'),{y:30,scale:.94,opacity:0},{y:0,scale:1,opacity:1,duration:.5,ease:'back.out(1.6)'});
  gsap.fromTo(resOk.querySelector('.check'),{scale:0,rotation:-40},{scale:1,rotation:0,duration:.6,ease:'back.out(2)',delay:.15});
});
document.getElementById('okClose').addEventListener('click',()=>{if(reduce){gsap.set(resOk,{display:'none'});return;}gsap.to(resOk,{opacity:0,duration:.3,onComplete:()=>gsap.set(resOk,{display:'none',opacity:1})});});

/* ============ CONTACT FORM ============ */
document.getElementById('ctForm').addEventListener('submit',e=>{
  e.preventDefault();if(!e.target.checkValidity()){e.target.reportValidity();return;}
  gsap.set(resOk,{display:'grid'});
  document.getElementById('okDet').innerHTML='';
  if(reduce){gsap.set(resOk.querySelector('.card'),{opacity:1,scale:1});return;}
  gsap.fromTo(resOk,{opacity:0},{opacity:1,duration:.3});
  gsap.fromTo(resOk.querySelector('.card'),{y:30,scale:.94,opacity:0},{y:0,scale:1,opacity:1,duration:.5,ease:'back.out(1.6)'});
  gsap.fromTo(resOk.querySelector('.check'),{scale:0,rotation:-40},{scale:1,rotation:0,duration:.6,ease:'back.out(2)',delay:.15});
  e.target.reset();
});

/* ============ STATS ============ */
document.querySelectorAll('.stat .num').forEach(num=>{
  const target=+num.dataset.count;const dec=String(target).includes('.');const suf=num.querySelector('em,span');const sHtml=suf?suf.outerHTML:'';
  ScrollTrigger.create({trigger:num,start:'top 85%',once:true,onEnter:()=>{
    if(reduce){num.innerHTML=(dec?target.toFixed(1):target)+sHtml;return;}
    gsap.to({v:0},{v:target,duration:2,ease:'power2.out',onUpdate:function(){const x=this.targets()[0].v;num.innerHTML=(dec?x.toFixed(1):Math.round(x))+sHtml;}});
  }});
});

/* ============ GENERIC FADE-UP ============ */
gsap.utils.toArray('.sec-head,.quote,.contact-grid > *').forEach(el=>gsap.from(el,{y:50,opacity:0,duration:.9,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 88%'}}));

/* ============ MAGNETIC BUTTONS ============ */
document.querySelectorAll('.btn').forEach(btn=>{
  btn.addEventListener('mousemove',e=>{if(reduce)return;const r=btn.getBoundingClientRect();gsap.to(btn,{x:(e.clientX-r.left-r.width/2)*.25,y:(e.clientY-r.top-r.height/2)*.35,duration:.4,ease:'power2.out'});});
  btn.addEventListener('mouseleave',()=>{if(!reduce)gsap.to(btn,{x:0,y:0,duration:.6,ease:'elastic.out(1,.4)'});});
});
document.querySelector('.burger').addEventListener('click',function(){this.classList.toggle('open');});

/* ============ INIT ============ */
renderLook();renderServices();renderCart();renderPros();renderDays();renderSlots();renderTeam();renderHours();updateOpen();renderSummary();updateSteps();updateFloat();bindCursor();
setInterval(updateOpen,60000);
setLang('ca');
</script>
</body>
</html>
