  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}
  .lang{display:flex;gap:.2rem;border:1px solid var(--line2);padding:.2rem}
  .lang button{border:0;background:transparent;font-family:var(--sans);font-size:.62rem;letter-spacing:.12em;font-weight:700;padding:.35rem .55rem;cursor:none;color:var(--mut-l);transition:.3s}
  .lang button.active{background:var(--ink);color:var(--paper)}
  .burger{display:none;flex-direction:column;gap:5px;background:none;border:0;cursor:none}
  .burger i{width:24px;height:2px;background:var(--ink);transition:.3s}

  /* BUTTONS */
  .btn{position:relative;display:inline-flex;align-items:center;gap:.6rem;padding:.9rem 1.6rem;font-size:.74rem;letter-spacing:.1em;text-transform:uppercase;font-weight:700;overflow:hidden;cursor:none;border:1.5px solid var(--ink);transition:color .35s var(--ease)}
  .btn .fill{position:absolute;inset:0;background:var(--ink);transform:translateY(101%);transition:transform .45s var(--ease);z-index:0}
  .btn span{position:relative;z-index:1}
  .btn:hover{color:var(--paper)}
  .btn:hover .fill{transform:translateY(0)}
  .btn.solid{background:var(--pine);color:var(--paper);border-color:var(--pine)}
  .btn.solid .fill{background:var(--ink);transform:translateY(0)}
  .btn.solid:hover{color:var(--paper)}
  .btn.solid:hover .fill{transform:translateY(-101%)}
  .btn.inv{border-color:var(--paper);color:var(--paper)}
  .btn.inv .fill{background:var(--pine-l)}
  .btn.inv:hover{color:var(--ink)}
  .btn .ar{transition:transform .35s var(--ease)}
  .btn:hover .ar{transform:translateX(4px)}

  /* ===== FEATURED VIEWER (apertura) ===== */
  .viewer{padding:clamp(6.5rem,12vh,9rem) 0 clamp(3rem,6vh,5rem);position:relative}
  .viewer-top{display:flex;justify-content:space-between;align-items:flex-end;gap:2rem;margin-bottom:1.6rem;flex-wrap:wrap}
  .viewer-top .idx{font-family:var(--disp);font-weight:800;font-size:.9rem;letter-spacing:.1em}
  .viewer-top .idx em{color:var(--mut-l)}
  .vstepper{display:flex;align-items:center;gap:.6rem}
  .vstepper button{width:46px;height:46px;border:1.5px solid var(--line2);background:transparent;cursor:none;font-size:1.1rem;color:var(--ink);transition:.3s;display:grid;place-items:center}
  .vstepper button:hover{background:var(--ink);color:var(--paper);border-color:var(--ink)}
  .viewer-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:1.4rem;align-items:stretch}
  .vstage{position:relative;background:var(--ink);overflow:hidden;min-height:clamp(360px,52vh,620px)}
  .vstage .vimg{position:absolute;inset:0;opacity:0;transition:opacity .7s var(--ease)}
  .vstage .vimg.on{opacity:1}
  .vstage .vimg img{transform:scale(1.06)}
  .vstage .vimg.on img{transform:scale(1)}
  .vstage .vimg{transition:opacity .7s var(--ease)}
  .vstage .vimg.on{transition:opacity .7s var(--ease)}
  .vbadge{position:absolute;top:1.2rem;left:1.2rem;z-index:3;background:var(--paper);color:var(--ink);font-size:.6rem;letter-spacing:.16em;text-transform:uppercase;font-weight:700;padding:.4rem .7rem}
  .vthumbs{position:absolute;bottom:1.2rem;left:1.2rem;z-index:3;display:flex;gap:.5rem}
  .vthumbs button{width:62px;height:44px;border:2px solid transparent;cursor:none;overflow:hidden;opacity:.6;transition:.3s}
  .vthumbs button.on{opacity:1;border-color:var(--paper)}
  .vpanel{background:var(--white);border:1.5px solid var(--ink);padding:clamp(1.6rem,3vw,2.4rem);display:flex;flex-direction:column}
  .vpanel .zone{font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;color:var(--pine);font-weight:700}
  .vpanel h2{font-family:var(--disp);font-weight:800;font-size:clamp(1.6rem,3vw,2.4rem);line-height:1;margin-top:.6rem;letter-spacing:-.01em}
  .vpanel .addr{color:var(--mut-l);font-size:.86rem;margin-top:.5rem}
  .vprice{font-family:var(--disp);font-weight:800;font-size:clamp(2.4rem,5vw,3.6rem);line-height:.9;margin:1.4rem 0 .2rem;letter-spacing:-.02em}
  .vprice small{font-family:var(--sans);font-size:.7rem;font-weight:600;color:var(--mut-l);letter-spacing:.06em}
  .vstats{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:1.2rem 0}
  .vstats div{padding:.9rem .4rem;text-align:center;border-right:1px solid var(--line)}
  .vstats div:last-child{border-right:0}
  .vstats b{font-family:var(--disp);font-weight:700;font-size:1.3rem;display:block}
  .vstats span{font-size:.58rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut-l)}
  /* floor plan */
  .vplan{margin-top:auto}
  .vplan .ph{font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;color:var(--mut-l);font-weight:700;margin-bottom:.6rem;display:flex;justify-content:space-between}
  .vplan .ph em{color:var(--pine)}
  .plan-svg{width:100%;height:auto;background:var(--paper);border:1px solid var(--line)}
  .plan-svg .room{fill:var(--paper2);stroke:var(--ink);stroke-width:1.5;transition:fill .3s;cursor:none}
  .plan-svg .room:hover,.plan-svg .room.hot{fill:var(--pine-l)}
  .plan-svg text{font-family:var(--sans);font-size:7px;fill:var(--ink);font-weight:600;pointer-events:none;letter-spacing:.04em}
  .vpanel .vcta{display:flex;gap:.7rem;margin-top:1.4rem}
  .vpanel .vcta .btn{flex:1;justify-content:center}

  /* TICKER */
  .ticker{background:var(--ink);color:var(--paper);padding:1rem 0;overflow:hidden;border-block:1px solid var(--ink)}
  .ticker .track{display:flex;gap:2.6rem;white-space:nowrap;width:max-content;font-size:.78rem;letter-spacing:.04em}
  .ticker .track span{display:inline-flex;align-items:center;gap:.7rem}
  .ticker .track .z{font-weight:700;text-transform:uppercase;letter-spacing:.1em;font-size:.66rem}
  .ticker .track .up{color:var(--pine-l)}
  .ticker .track .dn{color:#E08A7A}
  .ticker .dot{width:5px;height:5px;background:var(--line-d);display:inline-block}

  /* SEARCH + GRID */
  .search-sec{padding:clamp(5rem,11vh,9rem) 0}
  .sec-head{display:flex;justify-content:space-between;align-items:flex-end;gap:2rem;margin-bottom:clamp(2rem,5vh,3rem);flex-wrap:wrap}
  .sec-head h2{font-family:var(--disp);font-weight:800;font-size:clamp(2.2rem,6vw,5rem);line-height:.92;letter-spacing:-.02em}
  .sec-head .note{color:var(--mut-l);font-size:.84rem;max-width:26ch;text-align:right;line-height:1.6}
  .filters{display:grid;grid-template-columns:1.2fr 1fr 1fr 1.6fr auto;gap:1rem;align-items:end;border:1.5px solid var(--ink);background:var(--white);padding:1.2rem;margin-bottom:2.4rem}
  .field label{display:block;font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700;color:var(--mut-l);margin-bottom:.5rem}
  .field select{width:100%;background:var(--paper);border:1px solid var(--line2);padding:.7rem .8rem;font-family:var(--sans);font-size:.86rem;color:var(--ink);cursor:none;appearance:none}
  .prange{position:relative;height:38px}
  .prange .pvals{font-family:var(--disp);font-weight:700;font-size:.82rem;margin-bottom:.4rem;display:flex;justify-content:space-between}
  .prange .rail{position:relative;height:4px;background:var(--line2);top:8px}
  .prange .rail .fillr{position:absolute;height:100%;background:var(--pine)}
  .prange input[type=range]{position:absolute;width:100%;top:0;margin:0;pointer-events:none;-webkit-appearance:none;background:none;height:20px}
  .prange input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;pointer-events:auto;width:18px;height:18px;background:var(--ink);border:2px solid var(--paper);cursor:none;margin-top:0}
  .prange input[type=range]::-moz-range-thumb{pointer-events:auto;width:16px;height:16px;background:var(--ink);border:2px solid var(--paper);cursor:none}
  .filters .btn{height:46px}
  .pgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.4rem}
  .pcard{background:var(--white);border:1.5px solid var(--ink);position:relative;display:flex;flex-direction:column;transition:transform .4s var(--ease)}
  .pcard:hover{transform:translateY(-5px)}
  .pcard.feat{grid-column:span 2;grid-row:span 2}
  .pcard .pimg{position:relative;aspect-ratio:4/3;overflow:hidden;background:var(--ink)}
  .pcard.feat .pimg{aspect-ratio:auto;flex:1;min-height:300px}
  .pcard .pimg img{transition:transform 1s var(--ease)}
  .pcard:hover .pimg img{transform:scale(1.06)}
  .pcard .ptags{position:absolute;top:.8rem;left:.8rem;z-index:2;display:flex;gap:.4rem}
  .pcard .ptags .tag{background:var(--paper);color:var(--ink);border-color:var(--paper)}
  .pcard .ptags .tag.new{background:var(--pine);color:var(--paper);border-color:var(--pine)}
  .pcard .cmp{position:absolute;top:.8rem;right:.8rem;z-index:3;width:34px;height:34px;border:1.5px solid var(--paper);background:rgba(20,22,26,.4);color:var(--paper);cursor:none;display:grid;place-items:center;font-size:1rem;transition:.3s}
  .pcard .cmp.on{background:var(--pine-l);color:var(--ink);border-color:var(--pine-l)}
  .pcard .pbody{padding:1.2rem 1.3rem 1.4rem}
  .pcard .pzone{font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;color:var(--pine);font-weight:700}
  .pcard h3{font-family:var(--disp);font-weight:700;font-size:1.25rem;line-height:1.05;margin-top:.4rem}
  .pcard.feat h3{font-size:clamp(1.6rem,3vw,2.2rem)}
  .pcard .pmeta{display:flex;gap:1.2rem;margin-top:.8rem;font-size:.78rem;color:var(--mut-l)}
  .pcard .pmeta b{color:var(--ink);font-weight:700}
  .pcard .pfoot{display:flex;justify-content:space-between;align-items:center;margin-top:1.1rem;padding-top:1rem;border-top:1px solid var(--line)}
  .pcard .pprice{font-family:var(--disp);font-weight:800;font-size:1.4rem;letter-spacing:-.01em}
  .pcard.feat .pprice{font-size:clamp(1.8rem,3vw,2.4rem)}
  .pcard .pview{font-size:.66rem;letter-spacing:.14em;text-transform:uppercase;font-weight:700;border-bottom:1.5px solid var(--ink);padding-bottom:.2rem;cursor:none}
  .pempty{display:none;text-align:center;padding:3rem;color:var(--mut-l);font-size:.9rem;border:1.5px dashed var(--line2)}

  /* MAP */
  .map-sec{background:var(--ink);color:var(--paper);padding:clamp(5rem,11vh,9rem) 0}
  .map-grid{display:grid;grid-template-columns:1.3fr .7fr;gap:clamp(2rem,5vw,4rem);align-items:center}
  .map-svg{width:100%;height:auto}
  .map-svg .dist{fill:rgba(236,238,240,.05);stroke:var(--line-d);stroke-width:1.5;transition:fill .3s;cursor:none}
  .map-svg .dist:hover,.map-svg .dist.hot{fill:rgba(127,203,164,.22);stroke:var(--pine-l)}
  .map-svg .pin{fill:var(--pine-l);cursor:none}
  .map-svg .pin-pulse{fill:none;stroke:var(--pine-l);stroke-width:1.5;transform-origin:center;animation:ping 2s var(--ease) infinite}
  @keyframes ping{0%{r:4;opacity:.8}100%{r:18;opacity:0}}
  .map-svg text{font-family:var(--sans);font-size:9px;fill:var(--mut-d);font-weight:600;letter-spacing:.06em;pointer-events:none}
  .map-side h2{font-family:var(--disp);font-weight:800;font-size:clamp(2rem,5vw,4rem);line-height:.95;letter-spacing:-.02em}
  .map-side .lead{color:var(--mut-d);line-height:1.7;margin:1.2rem 0 1.8rem;max-width:34ch}
  .zinfo{border:1px solid var(--line-d);padding:1.4rem 1.6rem;min-height:120px}
  .zinfo .zn{font-family:var(--disp);font-weight:700;font-size:1.5rem}
  .zinfo .row{display:flex;justify-content:space-between;margin-top:.9rem;font-size:.84rem}
  .zinfo .row span{color:var(--mut-d)}
  .zinfo .row b{font-family:var(--disp);font-weight:700;color:var(--pine-l)}
  .zinfo .hint{color:var(--mut-d);font-size:.78rem;margin-top:.9rem}

  /* MORTGAGE */
  .mort-sec{padding:clamp(5rem,11vh,9rem) 0}
  .mort-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.4rem;align-items:stretch}
  .mort-card{border:1.5px solid var(--ink);background:var(--white);padding:clamp(1.6rem,3vw,2.6rem)}
  .mort-card h3{font-family:var(--disp);font-weight:800;font-size:1.5rem;margin-bottom:.3rem}
  .mort-card .sub{color:var(--mut-l);font-size:.86rem;margin-bottom:1.8rem}
  .mfield{margin-bottom:1.5rem}
  .mfield label{display:flex;justify-content:space-between;font-size:.62rem;letter-spacing:.16em;text-transform:uppercase;font-weight:700;color:var(--mut-l);margin-bottom:.7rem}
  .mfield label b{font-family:var(--disp);color:var(--pine);font-size:.95rem;letter-spacing:0}
  .mfield input[type=range]{width:100%;accent-color:var(--pine);cursor:none;height:3px}
  .mfield .seg{display:flex;gap:.4rem}
  .mfield .seg button{flex:1;border:1px solid var(--line2);background:var(--paper);padding:.6rem 0;font-family:var(--sans);font-size:.82rem;font-weight:600;cursor:none;transition:.3s}
  .mfield .seg button.on{background:var(--ink);color:var(--paper);border-color:var(--ink)}
  .mort-out{background:var(--ink);color:var(--paper);display:flex;flex-direction:column;justify-content:center}
  .mort-out .lbl{font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;color:var(--pine-l);font-weight:700}
  .mort-out .quota{font-family:var(--disp);font-weight:800;font-size:clamp(2.6rem,6vw,4.4rem);line-height:.9;margin:.6rem 0 .2rem;letter-spacing:-.02em}
  .mort-out .per{font-size:.74rem;color:var(--mut-d);letter-spacing:.06em}
  .mort-donut{display:flex;align-items:center;gap:1.4rem;margin-top:2rem}
  .mdonut{width:120px;height:120px;flex:none;transform:rotate(-90deg)}
  .mdonut circle{fill:none;stroke-width:14}
  .mdonut .bg{stroke:var(--line-d)}
  .mdonut .cap{stroke:var(--pine-l)}
  .mdonut .int{stroke:var(--steel)}
  .mleg{display:flex;flex-direction:column;gap:.8rem;font-size:.82rem}
  .mleg .li{display:flex;align-items:center;gap:.7rem}
  .mleg .sw{width:12px;height:12px;flex:none}
  .mleg .li span{color:var(--mut-d)}
  .mleg .li b{font-family:var(--disp);font-weight:700;margin-left:auto}
  .mort-out .legal{font-size:.62rem;color:var(--mut-d);margin-top:1.8rem;line-height:1.6;letter-spacing:.04em}

  /* COMPARE DRAWER */
  .cmp-fab{position:fixed;bottom:1.6rem;right:1.6rem;z-index:800;background:var(--pine);color:var(--paper);border:0;padding:1rem 1.4rem;font-family:var(--sans);font-size:.74rem;letter-spacing:.1em;text-transform:uppercase;font-weight:700;cursor:none;display:none;align-items:center;gap:.6rem;box-shadow:var(--hard)}
  .cmp-fab .n{background:var(--paper);color:var(--pine);width:22px;height:22px;display:grid;place-items:center;font-size:.74rem}
  .cmp-drawer{position:fixed;inset:0;z-index:9400;display:none}
  .cmp-drawer .ov{position:absolute;inset:0;background:rgba(20,22,26,.7)}
  .cmp-drawer .panel{position:absolute;right:0;top:0;bottom:0;width:min(94vw,860px);background:var(--paper);overflow-y:auto;padding:clamp(1.6rem,4vw,2.6rem)}
  .cmp-drawer .phead{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.6rem}
  .cmp-drawer .phead h3{font-family:var(--disp);font-weight:800;font-size:1.6rem}
  .cmp-drawer .close{background:none;border:1.5px solid var(--ink);width:42px;height:42px;cursor:none;font-size:1.2rem}
  .cmp-table{width:100%;border-collapse:collapse}
  .cmp-table th,.cmp-table td{text-align:left;padding:.9rem .8rem;border-bottom:1px solid var(--line);font-size:.86rem;vertical-align:top}
  .cmp-table th{font-size:.6rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mut-l);font-weight:700;width:120px}
  .cmp-table .col-h{font-family:var(--disp);font-weight:700;font-size:1.05rem}
  .cmp-table .col-img{height:90px;overflow:hidden;margin-bottom:.6rem}
  .cmp-table .rm{background:none;border:0;color:var(--pine);font-size:.66rem;letter-spacing:.1em;text-transform:uppercase;font-weight:700;cursor:none;margin-top:.5rem}

  /* AGENTS (editorial list, not equal cards) */
  .agents-sec{padding:clamp(5rem,11vh,9rem) 0;border-top:1px solid var(--line)}
  .agent{display:grid;grid-template-columns:.6fr 1.4fr;gap:clamp(1.5rem,4vw,4rem);align-items:center;padding:clamp(1.6rem,3vw,2.4rem) 0;border-bottom:1px solid var(--line);cursor:none}
  .agent:nth-child(even){grid-template-columns:1.4fr .6fr}
  .agent:nth-child(even) .aph{order:2}
  .aph{aspect-ratio:4/5;overflow:hidden;position:relative}
  .aph img{filter:grayscale(1);transition:filter .6s var(--ease),transform 1s var(--ease)}
  .agent:hover .aph img{filter:grayscale(0);transform:scale(1.05)}
  .aph .n{position:absolute;top:.8rem;left:.8rem;font-family:var(--disp);font-weight:800;font-size:1rem;background:var(--paper);padding:.2rem .5rem}
  .ainfo .role{font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;color:var(--pine);font-weight:700}
  .ainfo h3{font-family:var(--disp);font-weight:800;font-size:clamp(1.6rem,3.4vw,2.6rem);line-height:1;margin:.5rem 0 .8rem;letter-spacing:-.01em}
  .ainfo p{color:var(--mut-l);line-height:1.7;max-width:46ch}
  .ainfo .stats{display:flex;gap:2rem;margin-top:1.4rem}
  .ainfo .stats div b{font-family:var(--disp);font-weight:800;font-size:1.6rem;display:block}
  .ainfo .stats div span{font-size:.62rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mut-l)}

  /* WHY (asymmetric) */
  .why-sec{background:var(--paper2);padding:clamp(5rem,11vh,9rem) 0;border-block:1px solid var(--line)}
  .why-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:clamp(2rem,6vw,6rem);align-items:start}
  .why-grid h2{font-family:var(--disp);font-weight:800;font-size:clamp(2.2rem,6vw,5rem);line-height:.92;letter-spacing:-.02em}
  .why-list{display:flex;flex-direction:column}
  .why-item{display:grid;grid-template-columns:auto 1fr;gap:1.6rem;padding:1.6rem 0;border-top:1px solid var(--line2)}
  .why-item .wn{font-family:var(--disp);font-weight:800;font-size:clamp(1.6rem,3vw,2.4rem);color:var(--pine);line-height:.9}
  .why-item h4{font-family:var(--disp);font-weight:700;font-size:1.3rem}
  .why-item p{color:var(--mut-l);line-height:1.6;margin-top:.5rem;font-size:.9rem}

  /* STATS */
  .stats{padding:clamp(4rem,8vh,6rem) 0}
  .stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-top:1.5px solid var(--ink);border-bottom:1.5px solid var(--ink)}
  .stat{padding:2rem 1.4rem;border-right:1.5px solid var(--ink)}
  .stat:last-child{border-right:0}
  .stat .num{font-family:var(--disp);font-weight:800;font-size:clamp(2.6rem,6vw,4.6rem);line-height:.85;letter-spacing:-.02em}
  .stat .num em{color:var(--pine)}
  .stat .lbl{font-size:.66rem;letter-spacing:.18em;text-transform:uppercase;margin-top:.8rem;color:var(--mut-l);font-weight:700}

  /* TESTI */
  .testi{background:var(--ink);color:var(--paper);padding:clamp(5rem,11vh,8rem) 0}
  .testi-grid{display:grid;grid-template-columns:.7fr 1.3fr;gap:clamp(2rem,5vw,4rem);align-items:center}
  .testi blockquote{font-family:var(--disp);font-weight:600;font-size:clamp(1.5rem,3.4vw,2.6rem);line-height:1.15;letter-spacing:-.01em}
  .testi cite{font-style:normal;display:block;margin-top:1.6rem;font-size:.72rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut-d)}

  /* CTA + FORM */
  .cta-sec{padding:clamp(5rem,11vh,9rem) 0}
  .cta-box{background:var(--pine);color:var(--paper);padding:clamp(2.4rem,6vw,5rem);display:grid;grid-template-columns:1fr 1fr;gap:clamp(2rem,5vw,4rem);align-items:center;position:relative;overflow:hidden}
  .cta-box::after{content:"";position:absolute;right:-80px;bottom:-80px;width:300px;height:300px;border:40px solid rgba(236,238,240,.06)}
  .cta-box h2{font-family:var(--disp);font-weight:800;font-size:clamp(2rem,5vw,4rem);line-height:.95;letter-spacing:-.02em;position:relative}
  .cta-box .lead{color:var(--mut-d);line-height:1.7;margin-top:1.2rem;max-width:34ch;position:relative}
  form .frow{display:grid;grid-template-columns:1fr 1fr;gap:1rem;position:relative}
  .cfield{margin-bottom:1rem}
  .cfield.full{grid-column:1/-1}
  .cfield label{display:block;font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700;margin-bottom:.5rem;color:var(--mut-d)}
  .cfield input,.cfield select,.cfield textarea{width:100%;background:transparent;border:0;border-bottom:1.5px solid rgba(236,238,240,.4);padding:.6rem 0;font-family:var(--sans);font-size:.92rem;color:var(--paper);outline:none;cursor:none;transition:border-color .3s}
  .cfield textarea{resize:vertical;min-height:70px}
  .cfield input:focus,.cfield select:focus,.cfield textarea:focus{border-color:var(--paper)}
  .cfield select{appearance:none}
  .cfield select option{color:var(--ink)}
  .cta-box .btn{background:var(--paper);color:var(--pine);border-color:var(--paper);position:relative}
  .cta-box .btn .fill{background:var(--ink)}
  .cta-box .btn:hover{color:var(--paper)}

  .res-ok{position:fixed;inset:0;z-index:9500;background:rgba(20,22,26,.9);backdrop-filter:blur(8px);display:none;place-items:center;padding:1.5rem}
  .res-ok .card{background:var(--paper);color:var(--ink);padding:clamp(2rem,5vw,3.5rem);text-align:center;max-width:440px;border:1.5px solid var(--ink)}
  .res-ok .check{width:70px;height:70px;background:var(--pine);color:var(--paper);display:grid;place-items:center;margin:0 auto 1.2rem;font-family:var(--disp);font-weight:800;font-size:1.8rem}
  .res-ok h3{font-family:var(--disp);font-weight:800;font-size:1.8rem}
  .res-ok p{color:var(--mut-l);margin:1rem 0 1.6rem;line-height:1.6}

  /* FOOTER */
  footer{background:var(--ink);color:var(--paper);padding:clamp(4rem,8vh,6rem) 0 2rem}
  .foot-top{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:2.5rem;padding-bottom:3rem;border-bottom:1px solid var(--line-d)}
  .foot-brand p{color:var(--mut-d);margin-top:1.2rem;max-width:32ch;line-height:1.6;font-size:.9rem}
  .foot-col h4{font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;color:var(--pine-l);margin-bottom:1.2rem;font-weight:700}
  .foot-col a{display:block;font-size:.9rem;padding:.35rem 0;color:rgba(236,238,240,.75);transition:.3s}
  .foot-col a:hover{color:var(--paper);padding-left:.4rem}
  .foot-bot{display:flex;justify-content:space-between;align-items:center;padding-top:2rem;font-size:.7rem;letter-spacing:.08em;color:var(--mut-d);flex-wrap:wrap;gap:1rem}

  .img-fallback{background:repeating-linear-gradient(45deg,var(--ink2),var(--ink2) 14px,#2a2f36 14px,#2a2f36 28px)!important}
  .img-fallback img{display:none}

  @media(max-width:1000px){
    .menu{display:none}.burger{display:flex}
    .viewer-grid,.map-grid,.mort-grid,.cta-box,.testi-grid,.why-grid{grid-template-columns:1fr}
    .filters{grid-template-columns:1fr 1fr}
    .pgrid{grid-template-columns:1fr 1fr}
    .pcard.feat{grid-column:span 2;grid-row:auto}
    .pcard.feat .pimg{min-height:220px}
    .agent,.agent:nth-child(even){grid-template-columns:1fr}
    .agent:nth-child(even) .aph{order:0}
    .stats-grid{grid-template-columns:1fr 1fr}
    .stat:nth-child(2){border-right:0}
    .stat:nth-child(1),.stat:nth-child(2){border-bottom:1.5px solid var(--ink)}
    .foot-top{grid-template-columns:1fr 1fr}
    .live{display:none}
  }
  @media(max-width:600px){
    .filters{grid-template-columns:1fr}
    .pgrid{grid-template-columns:1fr}
    .pcard.feat{grid-column:span 1}
    .stats-grid{grid-template-columns:1fr}
    .stat{border-right:0;border-bottom:1.5px solid var(--ink)}
    .stat:last-child{border-bottom:0}
    form .frow{grid-template-columns:1fr}
    .foot-top{grid-template-columns:1fr}
    .vstats{grid-template-columns:1fr 1fr}
    .vstats div:nth-child(2){border-right:0}
    .vstats div:nth-child(1),.vstats div:nth-child(2){border-bottom:1px solid var(--line)}
    .sec-head .note{text-align:left}
  }
  @media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
