let curLang='ca';
function T(k){return I18N[curLang][k]!==undefined?I18N[curLang][k]:k;}
function setLang(lang){
  curLang=lang;document.documentElement.lang=lang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{const k=el.getAttribute('data-i18n');if(I18N[lang][k]!==undefined)el.innerHTML=I18N[lang][k];});
  document.querySelectorAll('.lang button').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));
  buildFilters();renderGrid();renderViewer(curView);renderMap();renderAgents();renderTicker();mortgage();renderCompare();
}
document.querySelectorAll('.lang button').forEach(b=>b.addEventListener('click',()=>setLang(b.dataset.lang)));

/* ============ FORMAT ============ */
function money(n){const loc=curLang==='en'?'en-IE':curLang==='es'?'es-ES':'ca-ES';return new Intl.NumberFormat(loc,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);}
function num(n){const loc=curLang==='en'?'en-IE':curLang==='es'?'es-ES':'ca-ES';return new Intl.NumberFormat(loc).format(n);}
function zName(id){return T('z_'+id);}
function tName(id){return T('t_'+id);}

/* ============ LAZY IMG + FALLBACK ============ */
function lazy(img){const s=img.getAttribute('data-src');if(!s)return;img.onerror=()=>img.parentElement.classList.add('img-fallback');img.src=s;}
document.querySelectorAll('img[data-src]').forEach(lazy);

/* ============ CURSOR ============ */
const cur=document.querySelector('.cursor'),ring=document.querySelector('.cursor-ring');
let mx=0,my=0,rx=0,ry=0;
window.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;cur.style.left=mx+'px';cur.style.top=my+'px';});
(function loop(){rx+=(mx-rx)*.18;ry+=(my-ry)*.18;ring.style.left=rx+'px';ring.style.top=ry+'px';requestAnimationFrame(loop);})();
function bindGrow(){document.querySelectorAll('a,button,.pcard,.agent,.vthumbs button,.dist,.room,.why-item').forEach(el=>{el.onmouseenter=()=>ring.classList.add('grow');el.onmouseleave=()=>ring.classList.remove('grow');});}

/* ============ LENIS ============ */
const lenis=new Lenis({duration:1.15,easing:t=>Math.min(1,1.001-Math.pow(2,-10*t))});
lenis.on('scroll',ScrollTrigger.update);
gsap.ticker.add(time=>lenis.raf(time*1000));
gsap.ticker.lagSmoothing(0);
document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href');if(id.length>1){e.preventDefault();lenis.scrollTo(id,{offset:-60});}}));
gsap.registerPlugin(ScrollTrigger);
const reduce=window.matchMedia('(prefers-reduced-motion:reduce)').matches;

/* ambient parallax */
gsap.to('body::before',{yPercent:8,ease:'none',scrollTrigger:{trigger:'body',start:'top top',end:'bottom bottom',scrub:true}});

/* ============ PRELOADER ============ */
const pcount=document.getElementById('pcount'),pbar=document.getElementById('pbar');
gsap.timeline()
.to({v:0},{v:PROPS.length*100/ (PROPS.length),duration:1.6,ease:'power2.inOut',onUpdate:function(){const v=Math.round(this.targets()[0].v);pcount.textContent=v;pbar.style.width=(v/(PROPS.length)*100)+'%';}})
.set(pcount,{textContent:PROPS.length})
.set(pbar,{width:'100%'})
.to('#preloader',{yPercent:-100,duration:1,ease:'expo.inOut'},'+=.25')
.add(()=>{if(!reduce)gsap.from('.viewer-grid > *',{y:40,opacity:0,duration:.9,stagger:.12,ease:'power3.out'});});

/* ============ HEADER ============ */
ScrollTrigger.create({start:80,onUpdate:s=>document.getElementById('header').classList.toggle('scrolled',s.progress>0)});

/* ============ FEATURED VIEWER ============ */
let curView=0;
function renderViewer(i){
  const p=PROPS[i];curView=i;
  const stage=document.getElementById('vstage');
  // images
  stage.querySelectorAll('.vimg').forEach(n=>n.remove());
  p.img.forEach((src,k)=>{const d=document.createElement('div');d.className='vimg'+(k===0?' on':'');d.innerHTML=`<img data-src="${src}" alt="">`;stage.insertBefore(d,stage.firstChild.nextSibling?stage.querySelector('.vbadge').nextSibling:stage.firstChild);lazy(d.querySelector('img'));});
  // re-append badge+thumbs on top
  // (simpler: ensure order)
  document.getElementById('vBadge').textContent=p.new?T('tag_new'):(tName(p.type));
  // thumbs
  const th=document.getElementById('vthumbs');th.innerHTML='';
  p.img.forEach((src,k)=>{const b=document.createElement('button');b.className=k===0?'on':'';b.innerHTML=`<img data-src="${src}" alt="">`;lazy(b.querySelector('img'));b.onclick=()=>{stage.querySelectorAll('.vimg').forEach((n,j)=>n.classList.toggle('on',j===k));th.querySelectorAll('button').forEach((n,j)=>n.classList.toggle('on',j===k));};th.appendChild(b);});
  // fix vimg order: rebuild cleanly
  stage.querySelectorAll('.vimg').forEach(n=>n.remove());
  const badge=stage.querySelector('.vbadge'),thumbs=stage.querySelector('.vthumbs');
  p.img.forEach((src,k)=>{const d=document.createElement('div');d.className='vimg'+(k===0?' on':'');d.innerHTML=`<img data-src="${src}" alt="">`;stage.insertBefore(d,badge);lazy(d.querySelector('img'));});
  // panel
  document.getElementById('vZone').textContent=zName(p.zone);
  document.getElementById('vTitle').textContent=p.title[curLang];
  document.getElementById('vAddr').textContent=p.addr[curLang];
  document.getElementById('vPrice').textContent=money(p.price);
  document.getElementById('vPriceM2').textContent=num(Math.round(p.price/p.m2))+' €/m²';
  document.getElementById('vM2').textContent=p.m2;
  document.getElementById('vBed').textContent=p.bed;
  document.getElementById('vBath').textContent=p.bath;
  document.getElementById('vFloor').textContent=p.floor;
  document.getElementById('vIdx').textContent=String(i+1).padStart(2,'0');
  document.getElementById('vTot').textContent=String(PROPS.length).padStart(2,'0');
  drawPlan(p);
  // compare button state
  document.getElementById('vCompare').classList.toggle('solid',compareSet.has(p.id));
  if(!reduce){gsap.from('.vpanel > *',{y:18,opacity:0,duration:.6,stagger:.05,ease:'power3.out'});}
}
function drawPlan(p){
  const svg=document.getElementById('planSvg');svg.innerHTML='';
  const scale=p.m2/120;
  ROOMS.forEach(r=>{
    const area=Math.max(4,Math.round((r.w*r.h)/100*scale*1.1));
    const rect=document.createElementNS('http://www.w3.org/2000/svg','rect');
    rect.setAttribute('class','room');rect.setAttribute('x',r.x);rect.setAttribute('y',r.y);rect.setAttribute('width',r.w);rect.setAttribute('height',r.h);
    const txt=document.createElementNS('http://www.w3.org/2000/svg','text');
    txt.setAttribute('x',r.x+5);txt.setAttribute('y',r.y+12);txt.textContent=T(r.key);
    const m2=document.createElementNS('http://www.w3.org/2000/svg','text');
    m2.setAttribute('x',r.x+5);m2.setAttribute('y',r.y+r.h-6);m2.setAttribute('fill','#234E3C');m2.textContent=area+' m²';
    const over=()=>{rect.classList.add('hot');document.getElementById('vRoom').textContent=T(r.key)+' · '+area+' m²';};
    const out=()=>{rect.classList.remove('hot');document.getElementById('vRoom').textContent='—';};
    rect.addEventListener('mouseenter',over);rect.addEventListener('mouseleave',out);
    svg.appendChild(rect);svg.appendChild(txt);svg.appendChild(m2);
  });
}
document.getElementById('vPrev').onclick=()=>renderViewer((curView-1+PROPS.length)%PROPS.length);
document.getElementById('vNext').onclick=()=>renderViewer((curView+1)%PROPS.length);
document.getElementById('vCompare').onclick=()=>{toggleCompare(PROPS[curView].id);renderViewer(curView);};

/* ============ TICKER ============ */
function renderTicker(){
  const tk=document.getElementById('ticker');tk.innerHTML='';
  const span=document.createElement('span');
  let html='';
  ZONES.forEach(z=>{const v=((z.id.charCodeAt(0)%7)-3);const up=v>=0;
    html+=`<span class="z">${zName(z.id)}</span><span>${num(z.avg)} €/m²</span><span class="${up?'up':'dn'}">${up?'▲':'▼'} ${Math.abs(v)*0.4+0.3}%</span><i class="dot"></i>`;});
  span.innerHTML=html;tk.appendChild(span);tk.appendChild(span.cloneNode(true));
  gsap.killTweensOf(tk);gsap.to(tk,{xPercent:-50,duration:30,ease:'none',repeat:-1});
}

/* ============ FILTERS + GRID ============ */
let fState={zone:'all',type:'all',bed:'any',min:150000,max:2500000};
function buildFilters(){
  const z=document.getElementById('fZone'),t=document.getElementById('fType'),b=document.getElementById('fBed');
  z.innerHTML=`<option value="all">${T('f_all')}</option>`+ZONES.map(x=>`<option value="${x.id}">${zName(x.id)}</option>`).join('');
  t.innerHTML=`<option value="all">${T('f_any')}</option>`+TYPES.map(x=>`<option value="${x.id}">${tName(x.id)}</option>`).join('');
  b.innerHTML=`<option value="any">${T('f_bedany')}</option>`+[1,2,3,4,5].map(n=>`<option value="${n}">${n}+</option>`).join('');
  z.value=fState.zone;t.value=fState.type;b.value=fState.bed;
  updatePriceLabels();
}
function matches(p){
  if(fState.zone!=='all'&&p.zone!==fState.zone)return false;
  if(fState.type!=='all'&&p.type!==fState.type)return false;
  if(fState.bed!=='any'&&p.bed<+fState.bed)return false;
  if(p.price<fState.min||p.price>fState.max)return false;
  return true;
}
function renderGrid(){
  const grid=document.getElementById('pgrid');grid.innerHTML='';
  const list=PROPS.filter(matches);
  document.getElementById('pempty').style.display=list.length?'none':'block';
  document.getElementById('liveCount').textContent=list.length;
  list.forEach((p,i)=>{
    const feat=p.feat&&i===0;
    const card=document.createElement('div');card.className='pcard'+(feat?' feat':'');
    card.innerHTML=`
      <div class="pimg">
        <div class="ptags"><span class="tag">${zName(p.zone)}</span>${p.new?`<span class="tag new">${T('tag_new')}</span>`:''}</div>
        <button class="cmp ${compareSet.has(p.id)?'on':''}" data-id="${p.id}" aria-label="compare">+</button>
        <img data-src="${p.img[0]}" alt="">
      </div>
      <div class="pbody">
        <span class="pzone">${tName(p.type)}</span>
        <h3>${p.title[curLang]}</h3>
        <div class="pmeta"><span><b>${p.m2}</b> m²</span><span><b>${p.bed}</b> ${T('v_bed')}</span><span><b>${p.bath}</b> ${T('v_bath')}</span></div>
        <div class="pfoot"><span class="pprice">${money(p.price)}</span><span class="pview" data-id="${p.id}">${T('p_view')}</span></div>
      </div>`;
    lazy(card.querySelector('img'));
    card.querySelector('.cmp').onclick=e=>{e.stopPropagation();toggleCompare(p.id);renderGrid();};
    card.querySelector('.pview').onclick=()=>{const idx=PROPS.findIndex(x=>x.id===p.id);renderViewer(idx);lenis.scrollTo('#viewer',{offset:-60});};
    card.querySelector('.pimg').addEventListener('click',()=>{const idx=PROPS.findIndex(x=>x.id===p.id);renderViewer(idx);lenis.scrollTo('#viewer',{offset:-60});});
    grid.appendChild(card);
  });
  if(!reduce)gsap.from(grid.children,{y:36,opacity:0,duration:.6,stagger:.06,ease:'power3.out'});
  bindGrow();
}
['fZone','fType','fBed'].forEach(id=>document.getElementById(id).addEventListener('change',e=>{const k=id==='fZone'?'zone':id==='fType'?'type':'bed';fState[k]=e.target.value;renderGrid();}));
document.getElementById('fReset').onclick=()=>{fState={zone:'all',type:'all',bed:'any',min:150000,max:2500000};document.getElementById('rMin').value=150000;document.getElementById('rMax').value=2500000;buildFilters();renderGrid();renderMap();};
// price double range
const rMin=document.getElementById('rMin'),rMax=document.getElementById('rMax');
function updatePriceLabels(){
  let mn=+rMin.value,mx=+rMax.value;if(mn>mx-50000){if(this===rMin)mn=mx-50000;else mx=mn+50000;rMin.value=mn;rMax.value=mx;}
  fState.min=mn;fState.max=mx;
  document.getElementById('pMin').textContent=money(mn);document.getElementById('pMax').textContent=money(mx);
  const span=2500000-150000;const a=(mn-150000)/span*100,b=(mx-150000)/span*100;
  const fl=document.getElementById('pFill');fl.style.left=a+'%';fl.style.width=(b-a)+'%';
}
rMin.addEventListener('input',function(){updatePriceLabels.call(this);renderGrid();});
rMax.addEventListener('input',function(){updatePriceLabels.call(this);renderGrid();});

/* ============ MAP ============ */
function renderMap(){
  const svg=document.getElementById('mapSvg');svg.innerHTML='';
  ZONES.forEach(z=>{
    const poly=document.createElementNS('http://www.w3.org/2000/svg','polygon');
    poly.setAttribute('class','dist');poly.setAttribute('points',z.poly);poly.dataset.zone=z.id;
    const stock=PROPS.filter(p=>p.zone===z.id).length;
    poly.addEventListener('mouseenter',()=>showZone(z));
    poly.addEventListener('click',()=>{fState.zone=z.id;document.getElementById('fZone').value=z.id;renderGrid();lenis.scrollTo('#search',{offset:-60});});
    svg.appendChild(poly);
    const pulse=document.createElementNS('http://www.w3.org/2000/svg','circle');
    pulse.setAttribute('class','pin-pulse');pulse.setAttribute('cx',z.pin[0]);pulse.setAttribute('cy',z.pin[1]);pulse.setAttribute('r','4');
    const pin=document.createElementNS('http://www.w3.org/2000/svg','circle');
    pin.setAttribute('class','pin');pin.setAttribute('cx',z.pin[0]);pin.setAttribute('cy',z.pin[1]);pin.setAttribute('r','4');
    const txt=document.createElementNS('http://www.w3.org/2000/svg','text');
    txt.setAttribute('x',z.pin[0]+9);txt.setAttribute('y',z.pin[1]+3);txt.textContent=zName(z.id);
    svg.appendChild(pulse);svg.appendChild(pin);svg.appendChild(txt);
  });
  showZone(ZONES[0]);
}
function showZone(z){
  document.querySelectorAll('.dist').forEach(d=>d.classList.toggle('hot',d.dataset.zone===z.id));
  const stock=PROPS.filter(p=>p.zone===z.id).length;
  document.getElementById('zName').textContent=zName(z.id);
  document.getElementById('zAvg').textContent=num(z.avg)+' €';
  document.getElementById('zStock').textContent=stock;
}

/* ============ MORTGAGE ============ */
let mYears=25;
const mPrice=document.getElementById('mPrice'),mDown=document.getElementById('mDown'),mRate=document.getElementById('mRate');
function mortgage(){
  const price=+mPrice.value,downP=+mDown.value,rate=+mRate.value/100;
  const down=price*downP/100,loan=price-down,n=mYears*12,i=rate/12;
  const quota=i===0?loan/n:loan*i/(1-Math.pow(1+i,-n));
  const totalPay=quota*n,interest=totalPay-loan;
  document.getElementById('mPriceOut').textContent=money(price);
  document.getElementById('mDownOut').textContent=downP+'%';
  document.getElementById('mRateOut').textContent=(+mRate.value).toFixed(1).replace('.',curLang==='en'?'.':',')+'%';
  document.getElementById('mQuota').textContent=money(Math.round(quota));
  document.getElementById('mLoan').textContent=T('m_loan')+': '+money(Math.round(loan));
  document.getElementById('mCapV').textContent=money(Math.round(loan));
  document.getElementById('mIntV').textContent=money(Math.round(interest));
  // donut
  const C=314.16,capShare=loan/totalPay;
  if(reduce){
    document.getElementById('mCap').style.strokeDashoffset=C*(1-capShare);
    document.getElementById('mInt').style.strokeDashoffset=C*(1-(1-capShare));
    document.getElementById('mInt').style.transform=`rotate(${capShare*360}deg)`;document.getElementById('mInt').style.transformOrigin='center';
    return;
  }
  gsap.to('#mCap',{strokeDashoffset:C*(1-capShare),duration:.9,ease:'power2.out',overwrite:'auto'});
  gsap.to('#mInt',{strokeDashoffset:C*(1-(1-capShare)),duration:.9,ease:'power2.out',overwrite:'auto'});
  document.getElementById('mInt').style.transform=`rotate(${capShare*360}deg)`;document.getElementById('mInt').style.transformOrigin='center';
}
[mPrice,mDown,mRate].forEach(el=>el.addEventListener('input',mortgage));
document.querySelectorAll('#mYears button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#mYears button').forEach(x=>x.classList.toggle('on',x===b));mYears=+b.dataset.y;mortgage();}));

/* ============ AGENTS ============ */
function renderAgents(){
  const list=document.getElementById('agentList');list.innerHTML='';
  AGENTS.forEach((a,i)=>{
    const el=document.createElement('div');el.className='agent';
    el.innerHTML=`
