      </div>`;
    lazy(el.querySelector('img'));list.appendChild(el);
  });
  if(!reduce)gsap.utils.toArray('.agent').forEach(el=>gsap.from(el,{y:40,opacity:0,duration:.8,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 85%'}}));
  bindGrow();
}

/* ============ COMPARE ============ */
const compareSet=new Set();
function toggleCompare(id){
  if(compareSet.has(id))compareSet.delete(id);
  else{if(compareSet.size>=3)return;compareSet.add(id);}
  document.getElementById('cmpN').textContent=compareSet.size;
  document.getElementById('cmpFab').style.display=compareSet.size?'flex':'none';
  renderCompare();
}
function renderCompare(){
  const body=document.getElementById('cmpBody');
  const ids=[...compareSet];
  if(!ids.length){body.innerHTML=`<p style="color:var(--mut-l)">${T('cmp_empty')}</p>`;return;}
  const rows=[['cmp_zone',p=>zName(p.zone)],['cmp_type',p=>tName(p.type)],['cmp_price',p=>money(p.price)],['cmp_m2',p=>p.m2+' m²'],['cmp_pm2',p=>num(Math.round(p.price/p.m2))+' €'],['cmp_bed',p=>p.bed],['cmp_bath',p=>p.bath],['cmp_floor',p=>p.floor]];
  let html='<table class="cmp-table"><tr><th></th>'+ids.map(id=>{const p=PROPS.find(x=>x.id===id);return `<td><div class="col-img"><img data-src="${p.img[0]}" alt=""></div><div class="col-h">${p.title[curLang]}</div><button class="rm" data-id="${id}">${T('cmp_rm')}</button></td>`;}).join('')+'</tr>';
  rows.forEach(([k,fn])=>{html+='<tr><th>'+T(k)+'</th>'+ids.map(id=>`<td>${fn(PROPS.find(x=>x.id===id))}</td>`).join('')+'</tr>';});
  html+='</table>';body.innerHTML=html;
  body.querySelectorAll('img[data-src]').forEach(lazy);
  body.querySelectorAll('.rm').forEach(b=>b.onclick=()=>{toggleCompare(b.dataset.id);renderGrid();renderViewer(curView);});
