  .cursor::before{left:50%;top:0;width:1.5px;height:100%;transform:translateX(-50%)}
  .cursor::after{top:50%;left:0;height:1.5px;width:100%;transform:translateY(-50%)}
  .cursor-ring{position:fixed;top:0;left:0;width:40px;height:40px;border:1.5px solid var(--paper);border-radius:50%;pointer-events:none;z-index:9998;transform:translate(-50%,-50%);transition:width .3s var(--ease),height .3s var(--ease),background .3s,border-color .3s}
  .cursor-ring.grow{width:74px;height:74px;background:rgba(242,194,0,.12);border-color:var(--signal)}
  @media(hover:none){body{cursor:auto}.cursor,.cursor-ring{display:none}}

  /* PRELOADER */
  #preloader{position:fixed;inset:0;background:var(--ink);color:var(--paper);z-index:10000;display:flex;flex-direction:column;justify-content:space-between;padding:clamp(1.4rem,4vw,3rem)}
  #preloader .top{display:flex;justify-content:space-between;align-items:center;font-family:var(--mono);font-size:.64rem;letter-spacing:.26em;text-transform:uppercase;opacity:.7}
  #preloader .mid{display:flex;align-items:flex-end;gap:1.4rem}
  #preloader .count{font-family:var(--disp);font-weight:800;font-size:clamp(4.5rem,20vw,15rem);line-height:.8;color:var(--signal)}
  #preloader .odo{font-family:var(--mono);font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:var(--mut-d);padding-bottom:1.4rem;line-height:1.7}
  #preloader .odo b{color:var(--paper);font-size:1rem}
  #preloader .bar{height:3px;background:var(--line-d);overflow:hidden}
  #preloader .bar i{display:block;height:100%;width:0;background:repeating-linear-gradient(90deg,var(--signal) 0 14px,transparent 14px 22px)}

  /* NAV */
  header{position:fixed;top:0;left:0;width:100%;z-index:900;transition:background .4s,backdrop-filter .4s}
  header.scrolled{background:rgba(43,46,51,.9);backdrop-filter:blur(12px);border-bottom:1px solid var(--line-d)}
  .nav{display:flex;align-items:center;justify-content:space-between;padding:1.05rem 0}
  .logo{font-family:var(--disp);font-weight:800;font-size:1.4rem;letter-spacing:.04em;display:flex;align-items:center;gap:.6rem}
  .logo .mk{width:24px;height:24px;position:relative;flex:none}
  .logo .mk::before{content:"";position:absolute;inset:0;border:2.5px solid var(--signal);border-radius:50%}
  .logo .mk::after{content:"";position:absolute;left:50%;top:50%;width:9px;height:9px;background:var(--signal);border-radius:50%;transform:translate(-50%,-50%)}
  .logo span{font-family:var(--mono);font-size:.52rem;letter-spacing:.26em;color:var(--mut-d);font-weight:500;text-transform:uppercase}
  .menu{display:flex;gap:1.9rem;list-style:none;font-family:var(--mono);font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;font-weight:500}
  .menu a{position:relative;padding:.3rem 0;color:rgba(243,241,234,.8)}
  .menu a::after{content:"";position:absolute;left:0;bottom:-3px;width:0;height:2px;background:var(--signal);transition:width .4s var(--ease)}
  .menu a:hover::after{width:100%}
  .nav-right{display:flex;align-items:center;gap:1rem}
  .lang{display:flex;gap:.2rem;border:1px solid var(--line-d);padding:.2rem}
  .lang button{border:0;background:transparent;font-family:var(--mono);font-size:.6rem;letter-spacing:.12em;font-weight:600;padding:.35rem .55rem;cursor:none;color:var(--mut-d);transition:.3s}
  .lang button.active{background:var(--signal);color:var(--ink)}
  .burger{display:none;flex-direction:column;gap:5px;background:none;border:0;cursor:none}
  .burger i{width:24px;height:2px;background:var(--paper);transition:.3s}

  /* BUTTONS */
  .btn{position:relative;display:inline-flex;align-items:center;gap:.6rem;padding:.9rem 1.6rem;font-family:var(--mono);font-size:.7rem;letter-spacing:.12em;text-transform:uppercase;font-weight:600;overflow:hidden;cursor:none;border:1.5px solid var(--paper);transition:color .35s var(--ease)}
  .btn .fill{position:absolute;inset:0;background:var(--paper);transform:translateY(101%);transition:transform .45s var(--ease);z-index:0}
  .btn span{position:relative;z-index:1}
  .btn:hover{color:var(--ink)}
  .btn:hover .fill{transform:translateY(0)}
  .btn.solid{background:var(--signal);color:var(--ink);border-color:var(--signal)}
  .btn.solid .fill{background:var(--ink);transform:translateY(0)}
  .btn.solid:hover{color:var(--signal)}
  .btn.solid:hover .fill{transform:translateY(-101%)}
  .btn.dark{border-color:var(--ink);color:var(--ink)}
  .btn.dark .fill{background:var(--ink)}
  .btn.dark:hover{color:var(--paper)}
  .btn .ar{transition:transform .35s var(--ease)}
  .btn:hover .ar{transform:translateX(4px)}

  /* ===== OPENING: DISPATCH + LIVE MAP ===== */
  .ops{padding:clamp(6.5rem,12vh,9rem) 0 clamp(2.5rem,5vh,4rem);position:relative}
  .ops-head{display:grid;grid-template-columns:1.2fr .8fr;gap:clamp(1.5rem,4vw,4rem);align-items:end;margin-bottom:1.8rem}
  .ops-head h1{font-family:var(--disp);font-weight:800;font-size:clamp(2.6rem,7.5vw,7rem);line-height:.9;letter-spacing:-.02em}
  .ops-head h1 .word{display:inline-block;overflow:hidden;vertical-align:top}
  .ops-head h1 .word i{display:inline-block;font-style:normal;transform:translateY(110%)}
  .ops-head h1 .out{-webkit-text-stroke:1.5px var(--paper);color:transparent}
  .ops-head .lead{color:var(--mut-d);line-height:1.7;font-size:.98rem;max-width:34ch;align-self:end}
  .ops-head .lead .live{display:inline-flex;align-items:center;gap:.5rem;color:var(--signal);font-family:var(--mono);font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;margin-bottom:.9rem}
  .ops-head .lead .live .led{width:7px;height:7px;border-radius:50%;background:var(--signal);box-shadow:0 0 9px var(--signal);animation:pulse 1.5s infinite}
  @keyframes pulse{0%,100%{opacity:1}50%{opacity:.3}}
  .ops-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:1.2rem;align-items:stretch}

  /* departures board */
  .board{background:var(--ink);border:1px solid var(--line-d);display:flex;flex-direction:column;overflow:hidden}
  .board-top{display:flex;justify-content:space-between;align-items:center;padding:.9rem 1.2rem;border-bottom:1px solid var(--line-d);background:var(--asphalt2)}
  .board-top .t{font-family:var(--mono);font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--signal);display:flex;align-items:center;gap:.6rem}
  .board-top .t .led{width:7px;height:7px;border-radius:50%;background:var(--signal);animation:pulse 1.5s infinite}
  .board-top .clk{font-family:var(--mono);font-size:.8rem;font-weight:600;letter-spacing:.08em}
  .board-head,.board-row{display:grid;grid-template-columns:.7fr 1.5fr 1fr .9fr;gap:.6rem;padding:.7rem 1.2rem;align-items:center}
  .board-head{font-family:var(--mono);font-size:.56rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut-d);border-bottom:1px solid var(--line-d)}
  .board-body{overflow:hidden}
  .board-row{border-bottom:1px solid rgba(243,241,234,.06);font-family:var(--mono);font-size:.8rem;transition:background .3s}
  .board-row:hover{background:var(--asphalt2)}
  .board-row .id{color:var(--mut-d);font-size:.72rem}
  .board-row .route{font-family:var(--sans);font-weight:500;font-size:.86rem;display:flex;align-items:center;gap:.5rem}
  .board-row .route .ar{color:var(--signal)}
  .board-row .eta{font-weight:600}
  .board-row .st{font-size:.58rem;letter-spacing:.1em;text-transform:uppercase;font-weight:600;padding:.25rem .5rem;display:inline-block}
  .st.route{background:rgba(84,124,255,.18);color:var(--cobalt2)}
  .st.load{background:rgba(242,194,0,.16);color:var(--signal2)}
  .st.free{background:rgba(127,203,164,.16);color:#7FCBA4}
  .st.late{background:rgba(224,138,122,.16);color:#E08A7A}
  .flip{display:inline-block}
  .board-foot{padding:.8rem 1.2rem;border-top:1px solid var(--line-d);display:flex;justify-content:space-between;font-family:var(--mono);font-size:.6rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut-d)}
  .board-foot b{color:var(--paper)}

  /* live map */
  .livemap{background:var(--asphalt2);border:1px solid var(--line-d);position:relative;overflow:hidden;min-height:380px}
  .livemap svg{width:100%;height:100%;display:block}
  .livemap .grid-l{stroke:rgba(243,241,234,.05);stroke-width:1}
  .livemap .route-p{fill:none;stroke:rgba(243,241,234,.16);stroke-width:2;stroke-linecap:round}
  .livemap .route-p.act{stroke:var(--signal);stroke-opacity:.5;stroke-dasharray:6 8}
  .livemap .stop{fill:var(--asphalt);stroke:var(--paper);stroke-width:1.5}
  .livemap .stop-lbl{font-family:var(--mono);font-size:7px;fill:var(--mut-d);letter-spacing:.04em}
  .livemap .veh{fill:var(--signal)}
  .livemap .veh.cob{fill:var(--cobalt2)}
  .livemap .veh-ring{fill:none;stroke:var(--signal);stroke-width:1.5;opacity:.6}
  .livemap .hud{position:absolute;top:1rem;left:1rem;z-index:3;display:flex;flex-direction:column;gap:.5rem}
  .livemap .hud .h{font-family:var(--mono);font-size:.58rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut-d)}
  .livemap .hud .odo{font-family:var(--disp);font-weight:800;font-size:1.7rem;color:var(--paper);line-height:1}
  .livemap .hud .odo small{font-family:var(--mono);font-size:.6rem;color:var(--signal);letter-spacing:.1em}
  .livemap .legend{position:absolute;bottom:1rem;left:1rem;z-index:3;display:flex;gap:1.2rem;font-family:var(--mono);font-size:.58rem;letter-spacing:.1em;text-transform:uppercase;color:var(--mut-d)}
  .livemap .legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:.4rem;vertical-align:middle}

  /* STATS STRIP */
  .strip{border-block:1px solid var(--line-d);padding:1.6rem 0;background:var(--asphalt2)}
  .strip-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}
  .strip .s{display:flex;align-items:baseline;gap:.8rem;padding:0 1rem;border-right:1px solid var(--line-d)}
  .strip .s:last-child{border-right:0}
  .strip .s .n{font-family:var(--disp);font-weight:800;font-size:clamp(1.8rem,3.5vw,2.8rem);line-height:.9;color:var(--paper)}
  .strip .s .n em{color:var(--signal);font-style:normal}
  .strip .s .l{font-family:var(--mono);font-size:.58rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mut-d);line-height:1.4}

  /* SECTION HEAD */
  .sec{padding:clamp(5rem,11vh,9rem) 0}
  .sec.light{background:var(--paper);color:var(--ink)}
  .sec.light .eyebrow{color:var(--cobalt)}
  .sec-head{display:flex;justify-content:space-between;align-items:flex-end;gap:2rem;margin-bottom:clamp(2rem,5vh,3rem);flex-wrap:wrap}
  .sec-head h2{font-family:var(--disp);font-weight:800;font-size:clamp(2.2rem,6vw,5rem);line-height:.92;letter-spacing:-.02em}
  .sec-head h2 .out{-webkit-text-stroke:1.5px currentColor;color:transparent}
  .sec-head .note{color:var(--mut-l);font-size:.86rem;max-width:28ch;text-align:right;line-height:1.6}
  .sec:not(.light) .sec-head .note{color:var(--mut-d)}

  /* FLEET — asymmetric spec sheets */
  .fleet-tabs{display:flex;gap:.5rem;flex-wrap:wrap;margin-bottom:1.6rem}
  .fleet-tabs button{font-family:var(--mono);font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;font-weight:600;padding:.7rem 1.1rem;border:1px solid var(--line-d);background:transparent;color:var(--mut-d);cursor:none;transition:.3s;display:flex;align-items:center;gap:.6rem}
  .fleet-tabs button .ic{font-size:1rem}
  .fleet-tabs button.on{background:var(--signal);color:var(--ink);border-color:var(--signal)}
  .fleet-show{display:grid;grid-template-columns:1.1fr .9fr;gap:1.2rem;align-items:stretch}
  .fleet-img{position:relative;overflow:hidden;background:var(--asphalt2);min-height:340px}
  .fleet-img img{position:absolute;inset:0;opacity:0;transition:opacity .6s var(--ease),transform 6s linear}
  .fleet-img img.on{opacity:1;transform:scale(1.06)}
  .fleet-img .vtag{position:absolute;top:1rem;left:1rem;z-index:2;background:var(--signal);color:var(--ink);font-family:var(--mono);font-size:.6rem;letter-spacing:.14em;text-transform:uppercase;font-weight:600;padding:.35rem .6rem}
  .fleet-spec{border:1px solid var(--line-d);background:var(--asphalt2);padding:clamp(1.6rem,3vw,2.4rem);display:flex;flex-direction:column}
  .fleet-spec h3{font-family:var(--disp);font-weight:800;font-size:clamp(1.8rem,3.4vw,2.8rem);line-height:.95;letter-spacing:-.01em}
  .fleet-spec .use{color:var(--mut-d);font-size:.9rem;line-height:1.6;margin-top:.8rem}
  .spec-grid{display:grid;grid-template-columns:1fr 1fr;gap:0;margin:1.6rem 0;border-top:1px solid var(--line-d)}
  .spec-grid .sp{padding:1rem 0;border-bottom:1px solid var(--line-d)}
  .spec-grid .sp:nth-child(odd){padding-right:1rem;border-right:1px solid var(--line-d)}
  .spec-grid .sp:nth-child(even){padding-left:1rem}
  .spec-grid .sp .k{font-family:var(--mono);font-size:.56rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut-d)}
  .spec-grid .sp .v{font-family:var(--disp);font-weight:700;font-size:1.5rem;margin-top:.3rem}
  .spec-grid .sp .v small{font-family:var(--mono);font-size:.62rem;color:var(--signal);font-weight:500}
  .fleet-spec .btn{margin-top:auto;align-self:flex-start}

  /* QUOTE CALC */
  .quote-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.2rem;align-items:stretch}
  .qcard{border:1.5px solid var(--ink);background:var(--white,#fff);padding:clamp(1.6rem,3vw,2.4rem)}
  .qcard{background:#fff}
  .qcard h3{font-family:var(--disp);font-weight:800;font-size:1.5rem}
  .qcard .sub{color:var(--mut-l);font-size:.86rem;margin:0 0 1.6rem}
  .qfield{margin-bottom:1.4rem}
  .qfield label{display:flex;justify-content:space-between;font-family:var(--mono);font-size:.6rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mut-l);font-weight:600;margin-bottom:.6rem}
  .qfield label b{color:var(--cobalt);font-size:.9rem}
  .qfield select{width:100%;background:var(--paper);border:1px solid var(--line2);padding:.7rem .8rem;font-family:var(--sans);font-size:.88rem;color:var(--ink);cursor:none;appearance:none}
  .qfield input[type=range]{width:100%;accent-color:var(--cobalt);cursor:none;height:3px}
  .qseg{display:flex;gap:.4rem}
  .qseg button{flex:1;border:1px solid var(--line2);background:var(--paper);padding:.6rem 0;font-family:var(--mono);font-size:.7rem;letter-spacing:.06em;font-weight:600;cursor:none;transition:.3s}
  .qseg button.on{background:var(--ink);color:var(--paper);border-color:var(--ink)}
  .qout{background:var(--ink);color:var(--paper);display:flex;flex-direction:column;justify-content:center}
  .qout .lbl{font-family:var(--mono);font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--signal)}
  .qout .price{font-family:var(--disp);font-weight:800;font-size:clamp(2.6rem,6vw,4.4rem);line-height:.9;margin:.5rem 0 .2rem;letter-spacing:-.02em}
  .qout .eta{font-family:var(--mono);font-size:.78rem;color:var(--mut-d);letter-spacing:.06em}
  .qout .eta b{color:var(--signal2)}
  .qroute{margin-top:1.8rem}
  .qroute .rl{display:flex;justify-content:space-between;font-family:var(--mono);font-size:.62rem;letter-spacing:.1em;text-transform:uppercase;color:var(--mut-d);margin-bottom:.5rem}
  .qroute .track{height:6px;background:var(--asphalt3);position:relative;overflow:hidden}
  .qroute .track .car{position:absolute;top:50%;width:14px;height:14px;background:var(--signal);border-radius:50%;transform:translate(-50%,-50%);left:0;box-shadow:0 0 0 4px rgba(242,194,0,.2)}
  .qbreak{margin-top:1.6rem;display:flex;flex-direction:column;gap:.6rem}
  .qbreak .br{display:flex;justify-content:space-between;font-size:.82rem}
  .qbreak .br span{color:var(--mut-d)}
  .qbreak .br b{font-family:var(--mono)}
  .qout .legal{font-family:var(--mono);font-size:.58rem;color:var(--mut-d);margin-top:1.6rem;line-height:1.6;letter-spacing:.04em}

  /* TRACKING */
  .track-sec{background:var(--asphalt2);border-block:1px solid var(--line-d)}
  .track-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:clamp(2rem,5vw,4rem);align-items:start}
  .track-in{display:flex;gap:.6rem;margin:1.4rem 0 1.6rem}
  .track-in input{flex:1;background:var(--asphalt);border:1px solid var(--line-d);padding:.9rem 1rem;font-family:var(--mono);font-size:.9rem;color:var(--paper);outline:none;cursor:none;letter-spacing:.06em}
  .track-in input:focus{border-color:var(--signal)}
  .track-hint{font-family:var(--mono);font-size:.62rem;letter-spacing:.1em;color:var(--mut-d);line-height:1.6}
  .track-hint code{color:var(--signal);background:var(--asphalt);padding:.1rem .4rem}
  .track-card{border:1px solid var(--line-d);background:var(--asphalt);padding:clamp(1.4rem,3vw,2.2rem)}
  .track-card .th{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.4rem;flex-wrap:wrap;gap:.6rem}
  .track-card .th .ref{font-family:var(--mono);font-size:.7rem;letter-spacing:.1em;color:var(--mut-d)}
  .track-card .th .ref b{color:var(--paper)}
  .track-card .th .est{font-family:var(--disp);font-weight:700;color:var(--signal)}
  .timeline{position:relative;padding-left:1.8rem}
  .timeline .tl-line{position:absolute;left:6px;top:6px;bottom:6px;width:2px;background:var(--asphalt3)}
  .timeline .tl-fill{position:absolute;left:6px;top:6px;width:2px;background:var(--signal);height:0}
  .tl-step{position:relative;padding:0 0 1.4rem 1.4rem}
  .tl-step:last-child{padding-bottom:0}
  .tl-step .dot{position:absolute;left:-1.8rem;top:.2rem;width:14px;height:14px;border-radius:50%;border:2px solid var(--asphalt3);background:var(--asphalt);transition:.5s var(--ease)}
  .tl-step.done .dot{background:var(--signal);border-color:var(--signal)}
  .tl-step.now .dot{background:var(--asphalt);border-color:var(--signal);box-shadow:0 0 0 4px rgba(242,194,0,.2)}
  .tl-step .when{font-family:var(--mono);font-size:.58rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut-d)}
  .tl-step .tt{font-family:var(--sans);font-weight:600;font-size:1rem;margin-top:.2rem;opacity:.45;transition:.5s}
  .tl-step.done .tt,.tl-step.now .tt{opacity:1}
  .tl-step .td{font-size:.8rem;color:var(--mut-d);margin-top:.2rem;opacity:0;transition:.5s}
  .tl-step.now .td{opacity:1}
  .track-mini{margin-top:1.4rem;border-top:1px solid var(--line-d);padding-top:1.2rem}
  .track-mini svg{width:100%;height:90px}
  .track-mini .rp{fill:none;stroke:var(--asphalt3);stroke-width:3;stroke-linecap:round}
  .track-mini .rp.done{stroke:var(--signal)}
  .track-mini .mk{fill:var(--signal)}

  /* COVERAGE */
  .cov-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1.5px solid var(--ink);border-left:1.5px solid var(--ink)}
  .cov{padding:clamp(1.4rem,2.5vw,2rem);border-right:1.5px solid var(--ink);border-bottom:1.5px solid var(--ink);position:relative;transition:background .4s var(--ease),color .4s;cursor:none;min-height:150px;display:flex;flex-direction:column;justify-content:space-between}
  .cov .zn{font-family:var(--disp);font-weight:800;font-size:clamp(1.3rem,2.4vw,1.9rem);line-height:1}
  .cov .meta{font-family:var(--mono);font-size:.62rem;letter-spacing:.1em;text-transform:uppercase;color:var(--mut-l);margin-top:.6rem}
  .cov .meta b{color:var(--cobalt)}
  .cov .ar{position:absolute;top:1.2rem;right:1.2rem;font-size:1.1rem;opacity:.3;transition:.4s var(--ease)}
  .cov:hover{background:var(--ink);color:var(--paper)}
  .cov:hover .meta{color:var(--mut-d)}
  .cov:hover .meta b{color:var(--signal)}
  .cov:hover .ar{opacity:1;transform:translate(3px,-3px);color:var(--signal)}

  /* HOW — route timeline, not equal cards */
  .how{position:relative;padding-left:0}
  .how-line{position:absolute;left:0;right:0;top:24px;height:2px;background:var(--line-d);z-index:0}
  .how-line .fill{height:100%;background:var(--signal);width:0}
  .how-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1.4rem;position:relative;z-index:1}
  .how-step{position:relative;padding-top:3.4rem}
  .how-step .node{position:absolute;top:14px;left:0;width:22px;height:22px;background:var(--asphalt);border:2px solid var(--signal);border-radius:50%;display:grid;place-items:center;font-family:var(--mono);font-size:.6rem;font-weight:600;color:var(--signal)}
  .how-step.on .node{background:var(--signal);color:var(--ink)}
  .how-step h4{font-family:var(--disp);font-weight:700;font-size:1.25rem;line-height:1.05}
  .how-step p{color:var(--mut-d);font-size:.86rem;line-height:1.6;margin-top:.6rem;max-width:24ch}

  /* TESTI */
  .testi-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1.2rem}
  .tcard{border:1px solid var(--line-d);background:var(--asphalt2);padding:clamp(1.6rem,3vw,2.4rem);position:relative}
  .tcard .q{font-family:var(--disp);font-weight:600;font-size:clamp(1.2rem,2.2vw,1.7rem);line-height:1.2;letter-spacing:-.01em}
  .tcard .q::before{content:"“";font-family:var(--disp);font-size:3rem;color:var(--signal);line-height:0;position:absolute;top:1.6rem;right:1.4rem;opacity:.4}
  .tcard .who{display:flex;align-items:center;gap:.9rem;margin-top:1.6rem}
  .tcard .who .av{width:42px;height:42px;border-radius:50%;overflow:hidden;flex:none;border:1.5px solid var(--signal)}
  .tcard .who .nm{font-weight:600;font-size:.9rem}
  .tcard .who .rl{font-family:var(--mono);font-size:.6rem;letter-spacing:.1em;text-transform:uppercase;color:var(--mut-d)}

  /* CTA */
  .cta-box{background:var(--signal);color:var(--ink);padding:clamp(2.4rem,6vw,5rem);display:grid;grid-template-columns:1fr 1fr;gap:clamp(2rem,5vw,4rem);align-items:center;position:relative;overflow:hidden}
  .cta-box::before{content:"";position:absolute;right:-60px;top:-60px;width:260px;height:260px;border:30px solid rgba(21,23,27,.07);border-radius:50%}
  .cta-box h2{font-family:var(--disp);font-weight:800;font-size:clamp(2rem,5vw,4rem);line-height:.95;letter-spacing:-.02em;position:relative}
  .cta-box .lead{line-height:1.7;margin-top:1.2rem;max-width:34ch;position:relative;font-weight:500}
  form .frow{display:grid;grid-template-columns:1fr 1fr;gap:1rem;position:relative}
  .cfield{margin-bottom:1rem}
  .cfield.full{grid-column:1/-1}
  .cfield label{display:block;font-family:var(--mono);font-size:.58rem;letter-spacing:.16em;text-transform:uppercase;font-weight:600;margin-bottom:.5rem;color:rgba(21,23,27,.6)}
  .cfield input,.cfield select,.cfield textarea{width:100%;background:transparent;border:0;border-bottom:1.5px solid rgba(21,23,27,.3);padding:.6rem 0;font-family:var(--sans);font-size:.92rem;color:var(--ink);outline:none;cursor:none;transition:border-color .3s}
  .cfield textarea{resize:vertical;min-height:70px}
  .cfield input:focus,.cfield select:focus,.cfield textarea:focus{border-color:var(--ink)}
  .cfield select{appearance:none}
  .cta-box .btn{background:var(--ink);color:var(--signal);border-color:var(--ink);position:relative}
  .cta-box .btn .fill{background:var(--paper)}
  .cta-box .btn:hover{color:var(--ink)}

  .res-ok{position:fixed;inset:0;z-index:9500;background:rgba(21,23,27,.92);backdrop-filter:blur(8px);display:none;place-items:center;padding:1.5rem}
  .res-ok .card{background:var(--paper);color:var(--ink);padding:clamp(2rem,5vw,3.5rem);text-align:center;max-width:440px}
  .res-ok .check{width:70px;height:70px;background:var(--ink);color:var(--signal);display:grid;place-items:center;margin:0 auto 1.2rem;font-family:var(--disp);font-weight:800;font-size:1.8rem;border-radius:50%}
  .res-ok h3{font-family:var(--disp);font-weight:800;font-size:1.8rem}
  .res-ok p{color:var(--mut-l);margin:1rem 0 1.6rem;line-height:1.6}

  /* FOOTER */
  footer{background:var(--ink);color:var(--paper);padding:clamp(4rem,8vh,6rem) 0 2rem;border-top:1px solid var(--line-d)}
  .foot-top{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:2.5rem;padding-bottom:3rem;border-bottom:1px solid var(--line-d)}
  .foot-brand p{color:var(--mut-d);margin-top:1.2rem;max-width:34ch;line-height:1.6;font-size:.9rem}
  .foot-col h4{font-family:var(--mono);font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--signal);margin-bottom:1.2rem;font-weight:600}
  .foot-col a{display:block;font-size:.9rem;padding:.35rem 0;color:rgba(243,241,234,.75);transition:.3s}
  .foot-col a:hover{color:var(--paper);padding-left:.4rem}
  .foot-bot{display:flex;justify-content:space-between;align-items:center;padding-top:2rem;font-family:var(--mono);font-size:.62rem;letter-spacing:.08em;color:var(--mut-d);flex-wrap:wrap;gap:1rem}

  .img-fallback{background:repeating-linear-gradient(45deg,var(--asphalt2),var(--asphalt2) 14px,var(--asphalt3) 14px,var(--asphalt3) 28px)!important}
  .img-fallback img{display:none}

  @media(max-width:1000px){
    .menu{display:none}.burger{display:flex}
    .ops-head,.ops-grid,.fleet-show,.quote-grid,.track-grid,.cta-box{grid-template-columns:1fr}
    .testi-grid{grid-template-columns:1fr}
    .cov-grid{grid-template-columns:1fr 1fr}
