  {id:'aeroport',x:60,y:340},
  {id:'port',x:230,y:300}
];
function dist(a,b){const za=ZONES.find(z=>z.id===a),zb=ZONES.find(z=>z.id===b);return Math.round(Math.hypot(za.x-zb.x,za.y-zb.y)/12*10)/10+1.2;}

const FLEET=[
  {id:'moto',img:'https://images.unsplash.com/photo-1558981806-ec527fa84c39?w=1100&q=80&auto=format&fit=crop',base:6,
