/* ============ LIVE ROUTE MAP ============ */
const liveMap=document.getElementById('liveMap');
let mapPaths=[],mapVehs=[];
function buildMap(){
  liveMap.innerHTML='';
  // grid
  for(let x=0;x<=400;x+=40){const l=document.createElementNS('http://www.w3.org/2000/svg','line');l.setAttribute('class','grid-l');l.setAttribute('x1',x);l.setAttribute('y1',0);l.setAttribute('x2',x);l.setAttribute('y2',380);liveMap.appendChild(l);}
  for(let y=0;y<=380;y+=38){const l=document.createElementNS('http://www.w3.org/2000/svg','line');l.setAttribute('class','grid-l');l.setAttribute('x1',0);l.setAttribute('y1',y);l.setAttribute('x2',400);l.setAttribute('y2',y);liveMap.appendChild(l);}
  mapPaths=[];mapVehs=[];
  ROUTES.forEach((rt,idx)=>{
    const a=ZONES.find(z=>z.id===rt.a),b=ZONES.find(z=>z.id===rt.b);
    const mx=(a.x+b.x)/2+(idx%2?30:-30),my=(a.y+b.y)/2+(idx%2?-20:20);
    const d=`M ${a.x} ${a.y} Q ${mx} ${my} ${b.x} ${b.y}`;
    const p=document.createElementNS('http://www.w3.org/2000/svg','path');
    p.setAttribute('class','route-p'+(rt.kind==='rep'?' act':''));p.setAttribute('d',d);
    if(rt.kind==='taxi')p.style.stroke='rgba(84,124,255,.4)';
    liveMap.appendChild(p);mapPaths.push({el:p,len:p.getTotalLength(),rt});
    // vehicle marker
    const ring=document.createElementNS('http://www.w3.org/2000/svg','circle');ring.setAttribute('class','veh-ring');ring.setAttribute('r','7');if(rt.kind==='taxi')ring.style.stroke='var(--cobalt2)';
    const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('class','veh'+(rt.kind==='taxi'?' cob':''));c.setAttribute('r','3.5');
    liveMap.appendChild(ring);liveMap.appendChild(c);
    mapVehs.push({c,ring,ph:rt.ph,sp:rt.sp});
  });
  // stops
  ZONES.forEach(z=>{
    const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('class','stop');c.setAttribute('cx',z.x);c.setAttribute('cy',z.y);c.setAttribute('r','3');liveMap.appendChild(c);
    const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('class','stop-lbl');t.setAttribute('x',z.x+6);t.setAttribute('y',z.y+3);t.textContent=zName(z.id);liveMap.appendChild(t);
  });
}
let odo=1842;
function animateMap(ts){
  mapVehs.forEach((v,i)=>{
    const mp=mapPaths[i];if(!mp)return;
    v.ph=(v.ph+v.sp)%1;
    const t=v.ph<.5?v.ph*2:(1-v.ph)*2; // ping-pong
    const pt=mp.el.getPointAtLength(t*mp.len);
    v.c.setAttribute('cx',pt.x);v.c.setAttribute('cy',pt.y);
    v.ring.setAttribute('cx',pt.x);v.ring.setAttribute('cy',pt.y);
  });
  odo+=0.06;document.getElementById('mapOdo').textContent=Math.round(odo).toLocaleString(curLang==='en'?'en-IE':curLang==='es'?'es-ES':'ca-ES');
  if(!reduce)requestAnimationFrame(animateMap);
}
buildMap();
if(reduce){mapVehs.forEach((v,i)=>{const mp=mapPaths[i];const pt=mp.el.getPointAtLength(.4*mp.len);v.c.setAttribute('cx',pt.x);v.c.setAttribute('cy',pt.y);v.ring.setAttribute('cx',pt.x);v.ring.setAttribute('cy',pt.y);});document.getElementById('mapOdo').textContent=Math.round(odo).toLocaleString('es-ES');}
else requestAnimationFrame(animateMap);

