/* ============ QUOTE ============ */
let qUrg='std';
function buildQuote(){
  const from=document.getElementById('qFrom'),to=document.getElementById('qTo');
  const opts=ZONES.map(z=>`<option value="${z.id}">${zName(z.id)}</option>`).join('');
  from.innerHTML=opts;to.innerHTML=opts;
  from.value='poblenou';to.value='centre';
  document.getElementById('qWeightOut').textContent=document.getElementById('qWeight').value+' kg';
}
function quote(){
  const from=document.getElementById('qFrom').value,to=document.getElementById('qTo').value;
  const w=+document.getElementById('qWeight').value;
  document.getElementById('qWeightOut').textContent=w+' kg';
  const f=FLEET[curFleet];
  const km=dist(from,to);
  const urgMul={std:1,exp:1.5,now:2.1}[qUrg];
  const weightMul=1+Math.min(w,120)/200;
  const base=f.base;
  const kmCost=km*1.1*weightMul;
  const urgSurcharge=(base+kmCost)*(urgMul-1);
  const total=Math.round((base+kmCost)*urgMul);
  const etaMin=Math.round(km*1.6*({std:1.4,exp:1,now:.7}[qUrg])+8);
  document.getElementById('qPrice').textContent=money(total);
  document.getElementById('qEta').textContent=etaMin+' '+T('q_min');
  document.getElementById('qBase').textContent=money(base);
  document.getElementById('qKm').textContent=km.toFixed(1)+' '+T('q_km_u');
  document.getElementById('qUrgV').textContent=money(Math.round(urgSurcharge));
  document.getElementById('qFromLbl').textContent=zName(from);
  document.getElementById('qToLbl').textContent=zName(to);
  // animate car along track by urgency (further = faster service visualised as progress)
  const prog={std:.4,exp:.7,now:.95}[qUrg];
  if(reduce){document.getElementById('qCar').style.left=prog*100+'%';}
  else gsap.to('#qCar',{left:prog*100+'%',duration:.9,ease:'power2.out',overwrite:'auto'});
  if(!reduce){gsap.fromTo('#qPrice',{opacity:.3,y:8},{opacity:1,y:0,duration:.4,ease:'power2.out',overwrite:'auto'});}
}
['qFrom','qTo','qWeight'].forEach(id=>document.getElementById(id).addEventListener('input',quote));
document.querySelectorAll('#qUrg button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#qUrg button').forEach(x=>x.classList.toggle('on',x===b));qUrg=b.dataset.u;quote();}));

