  const done=document.createElementNS('http://www.w3.org/2000/svg','path');done.setAttribute('class','rp done');done.setAttribute('d',d);done.setAttribute('stroke-dasharray',len);done.setAttribute('stroke-dashoffset',len*(1-prog));svg.appendChild(done);
