content:
Estoy asegurando que los textos visibles en los menús desplegables se actualicen según el idioma seleccionado, utilizando una función que reemplaza el contenido mediante innerHTML basado en atributos data-i18n. Los valores asociados a cada opción permanecen fijos en el HTML, lo que garantiza que los cálculos se realicen correctamente sin depender del texto visible. Esta separación entre presentación y datos permite mantener la funcionalidad intacta independientemente del idioma.  

```html
<!DOCTYPE html>
<html lang="ca">
<head>
  <meta charset="UTF-8" />
  <title>Calculadora de Reformes</title>
  <script>
    const translations = {
      "ca": {
        "titulo": "Calculadora de Reformes",
        "tipoReforma": "Tipus de reforma",
        "calidad": "Qualitat",
        "resultado": "Resultat",
        "btnCalcular": "Calcular",
        "integral": "Integral",
        "cuina": "Cuina",
        "bany": "Bany",
        "pintura": "Pintura",
        "std": "Estàndard",
        "prem": "Premium",
        "lux": "Lujo"
      },
      "es": {
        "titulo": "Calculadora de Reformas",
        "tipoReforma": "Tipo de reforma",
        "calidad": "Calidad",
        "resultado": "Resultado",
        "btnCalcular": "Calcular",
        "integral": "Integral",
        "cuina": "Cocina",
        "bany": "Baño",
        "pintura": "Pintura",
        "std": "Estándar",
        "prem": "Premium",
        "lux": "Lujo"
      },
      "en": {
        "titulo": "Renovation Calculator",
        "tipoReforma": "Type of renovation",
        "calidad": "Quality",
        "resultado": "Result",
        "btnCalcular": "Calculate",
        "integral": "Full renovation",
        "cuina": "Kitchen",
        "bany": "Bathroom",
        "pintura": "Painting",
        "std": "Standard",
        "prem": "Premium",
        "lux": "Luxury"
      }
    };

    function setLang(lang) {
      const elements = document.querySelectorAll('[data-i18n]');
      elements.forEach(el => {
        const key = el.getAttribute('data-i18n');
        const text = translations[lang][key];
        if (text) el.innerHTML = text;
      });
      document.documentElement.lang = lang;
    }

    function calcular() {
      const tipo = document.getElementById("tipo").value;
      const calidad = document.getElementById("calidad").value;

      const factores = {
        integral: { std: 1.0, prem: 1.3, lux: 1.6 },
        cuina: { std: 1.2, prem: 1.5, lux: 1.8 },
        bany: { std: 1.1, prem: 1.4, lux: 1.7 },
        pintura: { std: 0.8, prem: 1.0, lux: 1.2 }
      };

      const base = 1000;
      const factor = factores[tipo][calidad];
      const total = base * factor;

      document.getElementById("resultado").textContent = `€${total.toFixed(2)}`;
    }

    window.onload = () => {
      setLang("ca");
    };
  </script>
  <style>
    body { font-family: Arial, sans-serif; margin: 20px; }
    select, button { margin: 10px; padding: 8px; }
    #resultado { font-weight: bold; color: green; }
  </style>
</head>
<body>
  <h1 data-i18n="titulo"></h1>

  <label data-i18n="tipoReforma"></label>
  <select id="tipo">
    <option value="integral" data-i18n="integral"></option>
    <option value="cuina" data-i18n="cuina"></option>
    <option value="bany" data-i18n="bany"></option>
    <option value="pintura" data-i18n="pintura"></option>
  </select>

  <label data-i18n="calidad"></label>
  <select id="calidad">
    <option value="std" data-i18n="std"></option>
    <option value="prem" data-i18n="prem"></option>
    <option value="lux" data-i18n="lux"></option>
  </select>

  <button id="btnCalcular" data-i18n="btnCalcular" onclick="calcular()">Calcular</button>

  <p id="resultado" data-i18n="resultado"></p>
</body>
</html>
```

<answer>La interfaz está diseñada para soportar múltiples idiomas manteniendo valores fijos en el HTML para cálculos precisos. Los textos se actualizan dinámicamente mediante un sistema de traducción basado en atributos data-i18n, mientras que los valores de los selects no cambian, preservando la integridad del proceso de cálculo. Este enfoque permite una experiencia multilingüe fluida sin comprometer la funcionalidad técnica. El siguiente paso es probar el cambio de idioma y verificar que los cálculos sigan siendo correctos.

