let fState={zone:'all',type:'all',bed:'any',min:150000,max:2500000};
function buildFilters(){
  const z=document.getElementById('fZone'),t=document.getElementById('fType'),b=document.getElementById('fBed');
  z.innerHTML=`<option value="all">${T('f_all')}</option>`+ZONES.map(x=>`<option value="${x.id}">${zName(x.id)}</option>`).join('');
  t.innerHTML=`<option value="all">${T('f_any')}</option>`+TYPES.map(x=>`<option value="${x.id}">${tName(x.id)}</option>`).join('');
  b.innerHTML=`<option value="any">${T('f_bedany')}</option>`+[1,2,3,4,5].map(n=>`<option value="${n}">${n}+</option>`).join('');
  z.value=fState.zone;t.value=fState.type;b.value=fState.bed;
  updatePriceLabels();
}
function matches(p){
  if(fState.zone!=='all'&&p.zone!==fState.zone)return false;
  if(fState.type!=='all'&&p.type!==fState.type)return false;
  if(fState.bed!=='any'&&p.bed<+fState.bed)return false;
  if(p.price<fState.min||p.price>fState.max)return false;
  return true;
}
function renderGrid(){
  const grid=document.getElementById('pgrid');grid.innerHTML='';
  const list=PROPS.filter(matches);
  document.getElementById('pempty').style.display=list.length?'none':'block';
  document.getElementById('liveCount').textContent=list.length;
  list.forEach((p,i)=>{
    const feat=p.feat&&i===0;
    const card=document.createElement('div');card.className='pcard'+(feat?' feat':'');
    card.innerHTML=`
      <div class="pimg">
        <div class="ptags"><span class="tag">${zName(p.zone)}</span>${p.new?`<span class="tag new">${T('tag_new')}</span>`:''}</div>
        <button class="cmp ${compareSet.has(p.id)?'on':''}" data-id="${p.id}" aria-label="compare">+</button>
        <img data-src="${p.img[0]}" alt="">
      </div>
      <div class="pbody">
        <span class="pzone">${tName(p.type)}</span>
        <h3>${p.title[curLang]}</h3>
        <div class="pmeta"><span><b>${p.m2}</b> m²</span><span><b>${p.bed}</b> ${T('v_bed')}</span><span><b>${p.bath}</b> ${T('v_bath')}</span></div>
        <div class="pfoot"><span class="pprice">${money(p.price)}</span><span class="pview" data-id="${p.id}">${T('p_view')}</span></div>
      </div>`;
    lazy(card.querySelector('img'));
    card.querySelector('.cmp').onclick=e=>{e.stopPropagation();toggleCompare(p.id);renderGrid();};
    card.querySelector('.pview').onclick=()=>{const idx=PROPS.findIndex(x=>x.id===p.id);renderViewer(idx);lenis.scrollTo('#viewer',{offset:-60});};
    card.querySelector('.pimg').addEventListener('click',()=>{const idx=PROPS.findIndex(x=>x.id===p.id);renderViewer(idx);lenis.scrollTo('#viewer',{offset:-60});});
    grid.appendChild(card);
  });
  if(!reduce)gsap.from(grid.children,{y:36,opacity:0,duration:.6,stagger:.06,ease:'power3.out'});
  bindGrow();
}
['fZone','fType','fBed'].forEach(id=>document.getElementById(id).addEventListener('change',e=>{const k=id==='fZone'?'zone':id==='fType'?'type':'bed';fState[k]=e.target.value;renderGrid();}));
document.getElementById('fReset').onclick=()=>{fState={zone:'all',type:'all',bed:'any',min:150000,max:2500000};document.getElementById('rMin').value=150000;document.getElementById('rMax').value=2500000;buildFilters();renderGrid();renderMap();};
// price double range
const rMin=document.getElementById('rMin'),rMax=document.getElementById('rMax');
function updatePriceLabels(){
  let mn=+rMin.value,mx=+rMax.value;if(mn>mx-50000){if(this===rMin)mn=mx-50000;else mx=mn+50000;rMin.value=mn;rMax.value=mx;}
  fState.min=mn;fState.max=mx;
  document.getElementById('pMin').textContent=money(mn);document.getElementById('pMax').textContent=money(mx);
  const span=2500000-150000;const a=(mn-150000)/span*100,b=(mx-150000)/span*100;
  const fl=document.getElementById('pFill');fl.style.left=a+'%';fl.style.width=(b-a)+'%';
}
