/* ============ MORTGAGE ============ */
let mYears=25;
const mPrice=document.getElementById('mPrice'),mDown=document.getElementById('mDown'),mRate=document.getElementById('mRate');
function mortgage(){
  const price=+mPrice.value,downP=+mDown.value,rate=+mRate.value/100;
  const down=price*downP/100,loan=price-down,n=mYears*12,i=rate/12;
  const quota=i===0?loan/n:loan*i/(1-Math.pow(1+i,-n));
  const totalPay=quota*n,interest=totalPay-loan;
  document.getElementById('mPriceOut').textContent=money(price);
  document.getElementById('mDownOut').textContent=downP+'%';
  document.getElementById('mRateOut').textContent=(+mRate.value).toFixed(1).replace('.',curLang==='en'?'.':',')+'%';
  document.getElementById('mQuota').textContent=money(Math.round(quota));
  document.getElementById('mLoan').textContent=T('m_loan')+': '+money(Math.round(loan));
  document.getElementById('mCapV').textContent=money(Math.round(loan));
  document.getElementById('mIntV').textContent=money(Math.round(interest));
  // donut
  const C=314.16,capShare=loan/totalPay;
  if(reduce){
    document.getElementById('mCap').style.strokeDashoffset=C*(1-capShare);
    document.getElementById('mInt').style.strokeDashoffset=C*(1-(1-capShare));
    document.getElementById('mInt').style.transform=`rotate(${capShare*360}deg)`;document.getElementById('mInt').style.transformOrigin='center';
    return;
  }
  gsap.to('#mCap',{strokeDashoffset:C*(1-capShare),duration:.9,ease:'power2.out',overwrite:'auto'});
  gsap.to('#mInt',{strokeDashoffset:C*(1-(1-capShare)),duration:.9,ease:'power2.out',overwrite:'auto'});
  document.getElementById('mInt').style.transform=`rotate(${capShare*360}deg)`;document.getElementById('mInt').style.transformOrigin='center';
}
[mPrice,mDown,mRate].forEach(el=>el.addEventListener('input',mortgage));
document.querySelectorAll('#mYears button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#mYears button').forEach(x=>x.classList.toggle('on',x===b));mYears=+b.dataset.y;mortgage();}));

