  .spec-grid .sp:nth-child(even){padding-left:1rem}
  .spec-grid .sp .k{font-family:var(--mono);font-size:.56rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut-d)}
  .spec-grid .sp .v{font-family:var(--disp);font-weight:700;font-size:1.5rem;margin-top:.3rem}
  .spec-grid .sp .v small{font-family:var(--mono);font-size:.62rem;color:var(--signal);font-weight:500}
  .fleet-spec .btn{margin-top:auto;align-self:flex-start}

  /* QUOTE CALC */
  .quote-grid{display:grid;grid-template-columns:1fr 1fr;gap:1.2rem;align-items:stretch}
  .qcard{border:1.5px solid var(--ink);background:var(--white,#fff);padding:clamp(1.6rem,3vw,2.4rem)}
  .qcard{background:#fff}
  .qcard h3{font-family:var(--disp);font-weight:800;font-size:1.5rem}
  .qcard .sub{color:var(--mut-l);font-size:.86rem;margin:0 0 1.6rem}
  .qfield{margin-bottom:1.4rem}
  .qfield label{display:flex;justify-content:space-between;font-family:var(--mono);font-size:.6rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mut-l);font-weight:600;margin-bottom:.6rem}
  .qfield label b{color:var(--cobalt);font-size:.9rem}
  .qfield select{width:100%;background:var(--paper);border:1px solid var(--line2);padding:.7rem .8rem;font-family:var(--sans);font-size:.88rem;color:var(--ink);cursor:none;appearance:none}
  .qfield input[type=range]{width:100%;accent-color:var(--cobalt);cursor:none;height:3px}
  .qseg{display:flex;gap:.4rem}
  .qseg button{flex:1;border:1px solid var(--line2);background:var(--paper);padding:.6rem 0;font-family:var(--mono);font-size:.7rem;letter-spacing:.06em;font-weight:600;cursor:none;transition:.3s}
  .qseg button.on{background:var(--ink);color:var(--paper);border-color:var(--ink)}
  .qout{background:var(--ink);color:var(--paper);display:flex;flex-direction:column;justify-content:center}
  .qout .lbl{font-family:var(--mono);font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--signal)}
  .qout .price{font-family:var(--disp);font-weight:800;font-size:clamp(2.6rem,6vw,4.4rem);line-height:.9;margin:.5rem 0 .2rem;letter-spacing:-.02em}
  .qout .eta{font-family:var(--mono);font-size:.78rem;color:var(--mut-d);letter-spacing:.06em}
  .qout .eta b{color:var(--signal2)}
  .qroute{margin-top:1.8rem}
  .qroute .rl{display:flex;justify-content:space-between;font-family:var(--mono);font-size:.62rem;letter-spacing:.1em;text-transform:uppercase;color:var(--mut-d);margin-bottom:.5rem}
  .qroute .track{height:6px;background:var(--asphalt3);position:relative;overflow:hidden}
  .qroute .track .car{position:absolute;top:50%;width:14px;height:14px;background:var(--signal);border-radius:50%;transform:translate(-50%,-50%);left:0;box-shadow:0 0 0 4px rgba(242,194,0,.2)}
  .qbreak{margin-top:1.6rem;display:flex;flex-direction:column;gap:.6rem}
  .qbreak .br{display:flex;justify-content:space-between;font-size:.82rem}
  .qbreak .br span{color:var(--mut-d)}
  .qbreak .br b{font-family:var(--mono)}
  .qout .legal{font-family:var(--mono);font-size:.58rem;color:var(--mut-d);margin-top:1.6rem;line-height:1.6;letter-spacing:.04em}

  /* TRACKING */
  .track-sec{background:var(--asphalt2);border-block:1px solid var(--line-d)}
  .track-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:clamp(2rem,5vw,4rem);align-items:start}
  .track-in{display:flex;gap:.6rem;margin:1.4rem 0 1.6rem}
  .track-in input{flex:1;background:var(--asphalt);border:1px solid var(--line-d);padding:.9rem 1rem;font-family:var(--mono);font-size:.9rem;color:var(--paper);outline:none;cursor:none;letter-spacing:.06em}
  .track-in input:focus{border-color:var(--signal)}
  .track-hint{font-family:var(--mono);font-size:.62rem;letter-spacing:.1em;color:var(--mut-d);line-height:1.6}
  .track-hint code{color:var(--signal);background:var(--asphalt);padding:.1rem .4rem}
  .track-card{border:1px solid var(--line-d);background:var(--asphalt);padding:clamp(1.4rem,3vw,2.2rem)}
  .track-card .th{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.4rem;flex-wrap:wrap;gap:.6rem}
  .track-card .th .ref{font-family:var(--mono);font-size:.7rem;letter-spacing:.1em;color:var(--mut-d)}
  .track-card .th .ref b{color:var(--paper)}
  .track-card .th .est{font-family:var(--disp);font-weight:700;color:var(--signal)}
  .timeline{position:relative;padding-left:1.8rem}
  .timeline .tl-line{position:absolute;left:6px;top:6px;bottom:6px;width:2px;background:var(--asphalt3)}
  .timeline .tl-fill{position:absolute;left:6px;top:6px;width:2px;background:var(--signal);height:0}
  .tl-step{position:relative;padding:0 0 1.4rem 1.4rem}
  .tl-step:last-child{padding-bottom:0}
  .tl-step .dot{position:absolute;left:-1.8rem;top:.2rem;width:14px;height:14px;border-radius:50%;border:2px solid var(--asphalt3);background:var(--asphalt);transition:.5s var(--ease)}
  .tl-step.done .dot{background:var(--signal);border-color:var(--signal)}
  .tl-step.now .dot{background:var(--asphalt);border-color:var(--signal);box-shadow:0 0 0 4px rgba(242,194,0,.2)}
  .tl-step .when{font-family:var(--mono);font-size:.58rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut-d)}
  .tl-step .tt{font-family:var(--sans);font-weight:600;font-size:1rem;margin-top:.2rem;opacity:.45;transition:.5s}
  .tl-step.done .tt,.tl-step.now .tt{opacity:1}
  .tl-step .td{font-size:.8rem;color:var(--mut-d);margin-top:.2rem;opacity:0;transition:.5s}
  .tl-step.now .td{opacity:1}
  .track-mini{margin-top:1.4rem;border-top:1px solid var(--line-d);padding-top:1.2rem}
  .track-mini svg{width:100%;height:90px}
  .track-mini .rp{fill:none;stroke:var(--asphalt3);stroke-width:3;stroke-linecap:round}
  .track-mini .rp.done{stroke:var(--signal)}
  .track-mini .mk{fill:var(--signal)}

  /* COVERAGE */
  .cov-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1.5px solid var(--ink);border-left:1.5px solid var(--ink)}
  .cov{padding:clamp(1.4rem,2.5vw,2rem);border-right:1.5px solid var(--ink);border-bottom:1.5px solid var(--ink);position:relative;transition:background .4s var(--ease),color .4s;cursor:none;min-height:150px;display:flex;flex-direction:column;justify-content:space-between}
  .cov .zn{font-family:var(--disp);font-weight:800;font-size:clamp(1.3rem,2.4vw,1.9rem);line-height:1}
  .cov .meta{font-family:var(--mono);font-size:.62rem;letter-spacing:.1em;text-transform:uppercase;color:var(--mut-l);margin-top:.6rem}
  .cov .meta b{color:var(--cobalt)}
  .cov .ar{position:absolute;top:1.2rem;right:1.2rem;font-size:1.1rem;opacity:.3;transition:.4s var(--ease)}
  .cov:hover{background:var(--ink);color:var(--paper)}
  .cov:hover .meta{color:var(--mut-d)}
  .cov:hover .meta b{color:var(--signal)}
  .cov:hover .ar{opacity:1;transform:translate(3px,-3px);color:var(--signal)}

  /* HOW — route timeline, not equal cards */
  .how{position:relative;padding-left:0}
  .how-line{position:absolute;left:0;right:0;top:24px;height:2px;background:var(--line-d);z-index:0}
  .how-line .fill{height:100%;background:var(--signal);width:0}
  .how-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1.4rem;position:relative;z-index:1}
  .how-step{position:relative;padding-top:3.4rem}
  .how-step .node{position:absolute;top:14px;left:0;width:22px;height:22px;background:var(--asphalt);border:2px solid var(--signal);border-radius:50%;display:grid;place-items:center;font-family:var(--mono);font-size:.6rem;font-weight:600;color:var(--signal)}
  .how-step.on .node{background:var(--signal);color:var(--ink)}
  .how-step h4{font-family:var(--disp);font-weight:700;font-size:1.25rem;line-height:1.05}
  .how-step p{color:var(--mut-d);font-size:.86rem;line-height:1.6;margin-top:.6rem;max-width:24ch}

  /* TESTI */
  .testi-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1.2rem}
  .tcard{border:1px solid var(--line-d);background:var(--asphalt2);padding:clamp(1.6rem,3vw,2.4rem);position:relative}
  .tcard .q{font-family:var(--disp);font-weight:600;font-size:clamp(1.2rem,2.2vw,1.7rem);line-height:1.2;letter-spacing:-.01em}
  .tcard .q::before{content:"“";font-family:var(--disp);font-size:3rem;color:var(--signal);line-height:0;position:absolute;top:1.6rem;right:1.4rem;opacity:.4}
  .tcard .who{display:flex;align-items:center;gap:.9rem;margin-top:1.6rem}
  .tcard .who .av{width:42px;height:42px;border-radius:50%;overflow:hidden;flex:none;border:1.5px solid var(--signal)}
  .tcard .who .nm{font-weight:600;font-size:.9rem}
  .tcard .who .rl{font-family:var(--mono);font-size:.6rem;letter-spacing:.1em;text-transform:uppercase;color:var(--mut-d)}

  /* CTA */
  .cta-box{background:var(--signal);color:var(--ink);padding:clamp(2.4rem,6vw,5rem);display:grid;grid-template-columns:1fr 1fr;gap:clamp(2rem,5vw,4rem);align-items:center;position:relative;overflow:hidden}
  .cta-box::before{content:"";position:absolute;right:-60px;top:-60px;width:260px;height:260px;border:30px solid rgba(21,23,27,.07);border-radius:50%}
  .cta-box h2{font-family:var(--disp);font-weight:800;font-size:clamp(2rem,5vw,4rem);line-height:.95;letter-spacing:-.02em;position:relative}
  .cta-box .lead{line-height:1.7;margin-top:1.2rem;max-width:34ch;position:relative;font-weight:500}
  form .frow{display:grid;grid-template-columns:1fr 1fr;gap:1rem;position:relative}
  .cfield{margin-bottom:1rem}
  .cfield.full{grid-column:1/-1}
  .cfield label{display:block;font-family:var(--mono);font-size:.58rem;letter-spacing:.16em;text-transform:uppercase;font-weight:600;margin-bottom:.5rem;color:rgba(21,23,27,.6)}
  .cfield input,.cfield select,.cfield textarea{width:100%;background:transparent;border:0;border-bottom:1.5px solid rgba(21,23,27,.3);padding:.6rem 0;font-family:var(--sans);font-size:.92rem;color:var(--ink);outline:none;cursor:none;transition:border-color .3s}
  .cfield textarea{resize:vertical;min-height:70px}
  .cfield input:focus,.cfield select:focus,.cfield textarea:focus{border-color:var(--ink)}
  .cfield select{appearance:none}
  .cta-box .btn{background:var(--ink);color:var(--signal);border-color:var(--ink);position:relative}
  .cta-box .btn .fill{background:var(--paper)}
  .cta-box .btn:hover{color:var(--ink)}

  .res-ok{position:fixed;inset:0;z-index:9500;background:rgba(21,23,27,.92);backdrop-filter:blur(8px);display:none;place-items:center;padding:1.5rem}
  .res-ok .card{background:var(--paper);color:var(--ink);padding:clamp(2rem,5vw,3.5rem);text-align:center;max-width:440px}
  .res-ok .check{width:70px;height:70px;background:var(--ink);color:var(--signal);display:grid;place-items:center;margin:0 auto 1.2rem;font-family:var(--disp);font-weight:800;font-size:1.8rem;border-radius:50%}
  .res-ok h3{font-family:var(--disp);font-weight:800;font-size:1.8rem}
  .res-ok p{color:var(--mut-l);margin:1rem 0 1.6rem;line-height:1.6}

  /* FOOTER */
  footer{background:var(--ink);color:var(--paper);padding:clamp(4rem,8vh,6rem) 0 2rem;border-top:1px solid var(--line-d)}
  .foot-top{display:grid;grid-template-columns:1.6fr 1fr 1fr 1fr;gap:2.5rem;padding-bottom:3rem;border-bottom:1px solid var(--line-d)}
  .foot-brand p{color:var(--mut-d);margin-top:1.2rem;max-width:34ch;line-height:1.6;font-size:.9rem}
  .foot-col h4{font-family:var(--mono);font-size:.62rem;letter-spacing:.18em;text-transform:uppercase;color:var(--signal);margin-bottom:1.2rem;font-weight:600}
  .foot-col a{display:block;font-size:.9rem;padding:.35rem 0;color:rgba(243,241,234,.75);transition:.3s}
  .foot-col a:hover{color:var(--paper);padding-left:.4rem}
  .foot-bot{display:flex;justify-content:space-between;align-items:center;padding-top:2rem;font-family:var(--mono);font-size:.62rem;letter-spacing:.08em;color:var(--mut-d);flex-wrap:wrap;gap:1rem}

  .img-fallback{background:repeating-linear-gradient(45deg,var(--asphalt2),var(--asphalt2) 14px,var(--asphalt3) 14px,var(--asphalt3) 28px)!important}
  .img-fallback img{display:none}

  @media(max-width:1000px){
    .menu{display:none}.burger{display:flex}
    .ops-head,.ops-grid,.fleet-show,.quote-grid,.track-grid,.cta-box{grid-template-columns:1fr}
    .testi-grid{grid-template-columns:1fr}
    .cov-grid{grid-template-columns:1fr 1fr}
    .how-grid{grid-template-columns:1fr 1fr}
    .how-line{display:none}
    .strip-grid{grid-template-columns:1fr 1fr}
    .strip .s:nth-child(2){border-right:0}
    .strip .s:nth-child(1),.strip .s:nth-child(2){border-bottom:1px solid var(--line-d);padding-bottom:1rem}
    .strip .s:nth-child(3),.strip .s:nth-child(4){padding-top:1rem}
    .foot-top{grid-template-columns:1fr 1fr}
  }
  @media(max-width:600px){
    .cov-grid,.how-grid,.strip-grid{grid-template-columns:1fr}
    .strip .s{border-right:0;border-bottom:1px solid var(--line-d);padding:.8rem 0}
    .strip .s:last-child{border-bottom:0}
    form .frow{grid-template-columns:1fr}
    .foot-top{grid-template-columns:1fr}
    .board-head,.board-row{grid-template-columns:.6fr 1.4fr .8fr;font-size:.72rem}
    .board-head .c-eta,.board-row .eta{display:none}
    .spec-grid{grid-template-columns:1fr}
    .spec-grid .sp:nth-child(odd){padding-right:0;border-right:0}
    .spec-grid .sp:nth-child(even){padding-left:0}
    .sec-head .note{text-align:left}
  }
  @media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
</head>
<body>

<div class="cursor"></div>
<div class="cursor-ring"></div>

<div id="preloader">
  <div class="top"><span>RODAM · dispatch</span><span data-i18n="preloader">Posicionant flota</span></div>
  <div class="mid">
    <div class="count" id="pcount">0</div>
    <div class="odo"><span data-i18n="pre_odo">Km avui</span><br><b id="podo">000000</b></div>
  </div>
  <div><div class="bar"><i id="pbar"></i></div></div>
</div>

<header id="header">
  <div class="wrap nav">
    <a href="#" class="logo"><span class="mk"></span>RODAM<span data-i18n="logo_sub">logística urbana</span></a>
    <ul class="menu">
      <li><a href="#fleet" data-i18n="nav_fleet">Flota</a></li>
      <li><a href="#quote" data-i18n="nav_quote">Pressupost</a></li>
      <li><a href="#track" data-i18n="nav_track">Seguiment</a></li>
      <li><a href="#coverage" data-i18n="nav_cov">Cobertura</a></li>
      <li><a href="#contact" data-i18n="nav_contact">Contractar</a></li>
    </ul>
    <div class="nav-right">
      <div class="lang">
        <button data-lang="ca" class="active">CA</button>
        <button data-lang="es">ES</button>
        <button data-lang="en">EN</button>
      </div>
      <button class="burger" aria-label="menu"><i></i><i></i><i></i></button>
    </div>
  </div>
</header>

<!-- ===== OPENING: DISPATCH BOARD + LIVE MAP ===== -->
<section class="ops">
  <div class="wrap">
    <div class="ops-head">
      <h1 id="opsTitle">
        <span class="word"><i data-i18n="h_w1">La ciutat</i></span>
        <span class="word"><i data-i18n="h_w2">es</i></span>
        <span class="word"><i><span class="out" data-i18n="h_w3">mou</span></i></span><br>
        <span class="word"><i data-i18n="h_w4">amb</i></span>
        <span class="word"><i data-i18n="h_w5">nosaltres.</i></span>
      </h1>
      <div class="lead">
        <span class="live"><span class="led"></span><span data-i18n="h_live">Flota en viu · Barcelona</span></span>
        <p data-i18n="h_sub">Repartiment, missatgeria i taxi amb rutes optimitzades i seguiment en temps real. El que surt del nostre tauler, arriba.</p>
      </div>
    </div>

    <div class="ops-grid">
      <!-- DEPARTURES / DISPATCH BOARD -->
      <div class="board">
        <div class="board-top">
          <span class="t"><span class="led"></span><span data-i18n="board_t">Tauler de sortides</span></span>
          <span class="clk" id="boardClk">--:--:--</span>
        </div>
        <div class="board-head">
          <span data-i18n="bh_id">Unitat</span>
          <span data-i18n="bh_route">Ruta</span>
          <span class="c-eta" data-i18n="bh_eta">ETA</span>
          <span data-i18n="bh_st">Estat</span>
        </div>
        <div class="board-body" id="boardBody"></div>
        <div class="board-foot">
          <span><span data-i18n="bf_active">En servei</span> <b id="bfActive">0</b></span>
          <span><span data-i18n="bf_deliv">Lliuraments avui</span> <b id="bfDeliv">0</b></span>
          <span><span data-i18n="bf_ontime">Puntualitat</span> <b>98,4%</b></span>
        </div>
      </div>

      <!-- LIVE ROUTE MAP -->
      <div class="livemap">
        <div class="hud">
          <span class="h" data-i18n="map_odo">Odòmetre de flota</span>
          <div class="odo"><span id="mapOdo">0</span> <small>km</small></div>
        </div>
        <svg id="liveMap" viewBox="0 0 400 380" preserveAspectRatio="xMidYMid slice"></svg>
        <div class="legend">
          <span><i style="background:var(--signal)"></i><span data-i18n="lg_rep">Repartiment</span></span>
          <span><i style="background:var(--cobalt2)"></i><span data-i18n="lg_taxi">Taxi</span></span>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- STATS STRIP -->
<div class="strip">
  <div class="wrap strip-grid">
    <div class="s"><div class="n" data-count="64">0</div><div class="l" data-i18n="st1">Vehicles actius</div></div>
    <div class="s"><div class="n" data-count="1800">0<em>+</em></div><div class="l" data-i18n="st2">Lliuraments / dia</div></div>
    <div class="s"><div class="n" data-count="22">0</div><div class="l" data-i18n="st3">Minuts ETA mitjà</div></div>
    <div class="s"><div class="n" data-count="24">0<em>/7</em></div><div class="l" data-i18n="st4">Servei continu</div></div>
  </div>
</div>

<!-- FLEET -->
<section class="sec" id="fleet">
  <div class="wrap">
    <div class="sec-head">
      <h2 data-i18n="fleet_title">La <span class="out" data-i18n="fleet_out">flota</span></h2>
      <p class="note" data-i18n="fleet_note">Del sobre al palet, del trajecte a l'aeroport a la mudanza. Tria el vehicle que et cal.</p>
    </div>
    <div class="fleet-tabs" id="fleetTabs"></div>
    <div class="fleet-show">
      <div class="fleet-img" id="fleetImg"></div>
      <div class="fleet-spec" id="fleetSpec"></div>
    </div>
  </div>
</section>

<!-- QUOTE -->
<section class="sec light" id="quote">
  <div class="wrap">
    <div class="sec-head">
      <h2 data-i18n="quote_title">Quant <span class="out" data-i18n="quote_out">costa</span>?</h2>
      <p class="note" data-i18n="quote_note">Origen, destí, pes i urgència. Tens preu i ETA a l'instant, sense registrar-te.</p>
    </div>
    <div class="quote-grid">
      <div class="qcard">
        <h3 data-i18n="q_h">El teu enviament</h3>
        <p class="sub" data-i18n="q_sub">Càlcul orientatiu segons ruta i vehicle.</p>
        <div class="qfield"><label data-i18n="q_from">Origen</label><select id="qFrom"></select></div>
        <div class="qfield"><label data-i18n="q_to">Destí</label><select id="qTo"></select></div>
        <div class="qfield"><label><span data-i18n="q_weight">Pes</span><b id="qWeightOut">5 kg</b></label><input type="range" id="qWeight" min="0.5" max="120" step="0.5" value="5"></div>
        <div class="qfield"><label data-i18n="q_urg">Urgència</label><div class="qseg" id="qUrg"><button data-u="std" class="on" data-i18n="u_std">Estàndard</button><button data-u="exp" data-i18n="u_exp">Exprés</button><button data-u="now" data-i18n="u_now">Ara mateix</button></div></div>
      </div>
      <div class="qcard qout">
        <span class="lbl" data-i18n="q_price_lbl">Preu estimat</span>
        <div class="price" id="qPrice">—</div>
        <div class="eta"><span data-i18n="q_eta">Lliurament en</span> <b id="qEta">—</b></div>
        <div class="qroute">
          <div class="rl"><span id="qFromLbl">—</span><span id="qToLbl">—</span></div>
          <div class="track"><div class="car" id="qCar"></div></div>
        </div>
        <div class="qbreak">
