    row.innerHTML=`<span class="id">${r.id}</span><span class="route">${zName(r.from)} <span class="ar">→</span> ${zName(r.to)}</span><span class="eta">${r.st==='free'?'—':r.eta+' '+T('q_min')}</span><span><span class="st ${r.st}">${stLabel(r.st)}</span></span>`;
