function flipCell(row,sel,newHtml){
  const el=row.querySelector(sel);if(!el)return;
  if(reduce){el.innerHTML=newHtml;return;}
  gsap.to(el,{y:-6,opacity:0,duration:.18,ease:'power2.in',onComplete:()=>{el.innerHTML=newHtml;gsap.fromTo(el,{y:6,opacity:0},{y:0,opacity:1,duration:.22,ease:'power2.out'});}});
}
function liveBoard(){
  // mutate a couple of rows
  const i=Math.floor(Math.random()*board.length);
  const r=board[i];
  if(r.st==='route'){r.eta=Math.max(1,r.eta-1);if(r.eta<=1){r.st='load';r.eta=4;}}
  else if(r.st==='load'){r.st='route';r.eta=8+Math.floor(Math.random()*20);}
  else if(r.st==='free'){r.st='load';r.eta=3;}
  else{r.st='route';r.eta=10+Math.floor(Math.random()*15);}
  const rows=document.querySelectorAll('.board-row');
  if(rows[i]){
    flipCell(rows[i],'.eta',r.st==='free'?'—':r.eta+' '+T('q_min'));
    flipCell(rows[i],'.st',`<span class="st ${r.st}">${stLabel(r.st)}</span>`);
  }
  document.getElementById('bfActive').textContent=board.filter(x=>x.st!=='free').length;
}
renderBoard(true);
