/* ============ QUOTE ============ */
let qUrg='std';
function buildQuote(){
  const from=document.getElementById('qFrom'),to=document.getElementById('qTo');
  const opts=ZONES.map(z=>`<option value="${z.id}">${zName(z.id)}</option>`).join('');
  from.innerHTML=opts;to.innerHTML=opts;
  from.value='poblenou';to.value='centre';
  document.getElementById('qWeightOut').textContent=document.getElementById('qWeight').value+' kg';
}
function quote(){
  const from=document.getElementById('qFrom').value,to=document.getElementById('qTo').value;
  const w=+document.getElementById('qWeight').value;
  document.getElementById('qWeightOut').textContent=w+' kg';
  const f=FLEET[curFleet];
  const km=dist(from,to);
  const urgMul={std:1,exp:1.5,now:2.1}[qUrg];
  const weightMul=1+Math.min(w,120)/200;
  const base=f.base;
  const kmCost=km*1.1*weightMul;
  const urgSurcharge=(base+kmCost)*(urgMul-1);
  const total=Math.round((base+kmCost)*urgMul);
  const etaMin=Math.round(km*1.6*({std:1.4,exp:1,now:.7}[qUrg])+8);
  document.getElementById('qPrice').textContent=money(total);
  document.getElementById('qEta').textContent=etaMin+' '+T('q_min');
  document.getElementById('qBase').textContent=money(base);
  document.getElementById('qKm').textContent=km.toFixed(1)+' '+T('q_km_u');
  document.getElementById('qUrgV').textContent=money(Math.round(urgSurcharge));
  document.getElementById('qFromLbl').textContent=zName(from);
  document.getElementById('qToLbl').textContent=zName(to);
  // animate car along track by urgency (further = faster service visualised as progress)
  const prog={std:.4,exp:.7,now:.95}[qUrg];
  if(reduce){document.getElementById('qCar').style.left=prog*100+'%';}
  else gsap.to('#qCar',{left:prog*100+'%',duration:.9,ease:'power2.out',overwrite:'auto'});
  if(!reduce){gsap.fromTo('#qPrice',{opacity:.3,y:8},{opacity:1,y:0,duration:.4,ease:'power2.out',overwrite:'auto'});}
}
['qFrom','qTo','qWeight'].forEach(id=>document.getElementById(id).addEventListener('input',quote));
document.querySelectorAll('#qUrg button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#qUrg button').forEach(x=>x.classList.toggle('on',x===b));qUrg=b.dataset.u;quote();}));

/* ============ TRACKING ============ */
function renderTimeline(){
  const tl=document.getElementById('timeline');
  tl.querySelectorAll('.tl-step').forEach(n=>n.remove());
  TRACK_STEPS.forEach((s,i)=>{
    const cls=i<trackProgress?'done':i===trackProgress?'now':'';
    const el=document.createElement('div');el.className='tl-step '+cls;
    el.innerHTML=`<span class="dot"></span><div class="when">${i<=trackProgress?s.when:'—'}</div><div class="tt">${T(s.k)}</div><div class="td">${T(s.k+'d')}</div>`;
    tl.appendChild(el);
  });
  const fillPct=trackProgress/(TRACK_STEPS.length-1)*100;
  if(reduce){document.getElementById('tlFill').style.height=fillPct+'%';}
  else gsap.to('#tlFill',{height:fillPct+'%',duration:.9,ease:'power2.out'});
  // estimate
  const left=TRACK_STEPS.length-1-trackProgress;
  document.getElementById('trEst').textContent=left>0?(left*12)+' '+T('q_min'):T('ts5');
  if(!reduce)gsap.from('.tl-step',{x:-12,opacity:0,duration:.4,stagger:.08,ease:'power2.out'});
}
function renderTrackMini(){
  const svg=document.getElementById('trackMini');svg.innerHTML='';
  const d='M 10 70 C 80 10, 140 90, 200 40 S 300 20, 310 50';
  const base=document.createElementNS('http://www.w3.org/2000/svg','path');base.setAttribute('class','rp');base.setAttribute('d',d);svg.appendChild(base);
  const len=base.getTotalLength();
  const prog=trackProgress/(TRACK_STEPS.length-1);
  const done=document.createElementNS('http://www.w3.org/2000/svg','path');done.setAttribute('class','rp done');done.setAttribute('d',d);done.setAttribute('stroke-dasharray',len);done.setAttribute('stroke-dashoffset',len*(1-prog));svg.appendChild(done);
  const pt=base.getPointAtLength(prog*len);
  const mk=document.createElementNS('http://www.w3.org/2000/svg','circle');mk.setAttribute('class','mk');mk.setAttribute('cx',pt.x);mk.setAttribute('cy',pt.y);mk.setAttribute('r','5');svg.appendChild(mk);
  // origin/dest dots
  const o=base.getPointAtLength(0),e=base.getPointAtLength(len);
  [o,e].forEach(p=>{const c=document.createElementNS('http://www.w3.org/2000/svg','circle');c.setAttribute('cx',p.x);c.setAttribute('cy',p.y);c.setAttribute('r','3');c.setAttribute('fill','#40454E');svg.appendChild(c);});
}
