});
document.querySelector('.burger').addEventListener('click',function(){this.classList.toggle('open');});

/* ============ INIT ============ */
buildMap();renderFleet();buildQuote();quote();renderCoverage();renderHow();renderTesti();renderTimeline();renderTrackMini();bindGrow();
